window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[47]={"id":"047","numero":47,"titre":"Suivi médical pédiatrique","objectifs":[{"id":"47-1","rang":"A","rubrique":"Définition","titre":"Connaître les définitions des tranches d’âge des enfants","contenu":"<p>Entre la fécondation et l'adolescence, l'enfant traverse <strong><span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>4</span> g</span>randes étapes</strong> définies par l'âge :</p>\n\n      <table >\n        <thead><tr><th>Tranche</th><th>Bornes</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Nouveau-né</strong></td><td>&lt; <span class=\"kw-chiffre\">1 mois</span></td></tr>\n          <tr><td><strong>Nourrisson</strong></td><td><span class=\"kw-chiffre\">1 mois – 2 ans</span></td></tr>\n          <tr><td><strong>Jeune et grand enfant</strong></td><td><span class=\"kw-chiffre\">2 ans – début de puberté</span></td></tr>\n          <tr><td><strong>Adolescent</strong></td><td>après le début de la <strong>puberté</strong></td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>5 axes de <span class=\"kw-def\">surveillance</span> évolutive</strong> — psychomoteur/intellectuel · staturo-pondéral · <span class=\"kw-def\">dépistage</span> de handicaps · couverture nutritionnelle · prévention infectieuse (vaccinations).\n      </div>","frequence":0},{"id":"47-2","rang":"A","rubrique":"Prise en charge","titre":"Connaître les éléments d’interrogatoire et d’examen clinique systématique d’un enfant en fonction de son âge et du contexte","contenu":"<p>L'examen systématique de l'enfant repose sur l'interrogatoire des parents (puis de l'enfant dès qu'il peut s'exprimer) et un examen clinique adapté à l'âge.</p>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Interrogatoire (à adapter à l'âge)</h4>\n      <ul>\n        <li><strong>ATCD familiaux</strong> : pathologies, <span class=\"kw-alerte\">mort subite</span>, FR <span class=\"kw-bio\">CV</span>, maladies héréditaires ;</li>\n        <li><strong>ATCD personnels</strong> : <span class=\"kw-ci\">grossesse</span>, accouchement, période néonatale, hospitalisations, allergies, intolérances ;</li>\n        <li><strong>Vaccinations</strong> : calendrier obl<span class=\"kw-chiffre\">iga</span>toire et recommandé ;</li>\n        <li><strong>Alimentation</strong> : <span class=\"kw-ci\">allaitement</span>, diversification, équilibre alimentaire selon l'âge ;</li>\n        <li><strong>Développement</strong> : étapes psychomotrices, langage, scolarité, sommeil, propreté ;</li>\n        <li><strong>Environnement</strong> : mode de garde, fratrie, animaux, habitat (saturnisme), exposition aux écrans.</li>\n      </ul>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Examen clinique systématique</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Poids, taille, périmètre crânien (PC jusqu'à 3 ans), IMC</span> reportés sur <span class=\"kw-clinique\">les</span> courbes de croissance ;</li>\n        <li>Examen <strong>somatique général</strong> : cardio-pulmonaire, abdominal, ORL, neurologique, peau ;</li>\n        <li><strong>Dépistages sensoriels</strong> (visuels, auditifs) et <strong>orthopédiques</strong> (LCH jusqu'à la marche, scoliose à l'adolescence) ;</li>\n        <li><strong>Développement psychomoteur</strong> selon l'âge ;</li>\n        <li><strong>Examen bucco-dentaire</strong>, <span class=\"kw-ttt\">vaccination</span>, statut pubertaire (Tanner) après <span class=\"kw-chiffre\">8 ans</span>.</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 32 — Nouveau-né · 48 — Alimentation · 53 — Croissance · 55 — Développement psychomoteur · 146 — <span class=\"kw-ttt\">Vaccination</span></em></p>","frequence":0},{"id":"47-3","rang":"B","rubrique":"Prise en charge","titre":"Connaître les recommandations professionnelles du suivi des nourrissons et enfants","contenu":"<p>Le <span class=\"kw-def\">suivi</span> pédiatrique systématique est encadré par <strong>20 examens obl<span class=\"kw-chiffre\">iga</span>toires jusqu'à<span class=\"kw-chiffre\"> 16 ans</span></strong>, dont 14 dans <span class=\"kw-clinique\">les</span> 3 premières années.</p>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Calendrier officiel</h4>\n      <table >\n        <thead><tr><th>Période</th><th>Nombre / Repères</th></tr></thead>\n        <tbody>\n          <tr><td>Total jusqu'à<span class=\"kw-chiffre\"> 16 ans</span></td><td><span class=\"kw-chiffre\">20 examens obligatoires</span></td></tr>\n          <tr><td>3 premières années</td><td><span class=\"kw-chiffre\">14 examens</span></td></tr>\n          <tr><td><span class=\"kw-chiffre\">4–17 ans</span></td><td><span class=\"kw-chiffre\">6 examens</span></td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Qui réalise ces examens ?</h4>\n      <ul>\n        <li>Médecin traitant (pédiatre, généraliste) <strong>ou médecin de PMI</strong> : jusqu'à <span class=\"kw-chiffre\">6 ans</span> ;</li>\n        <li>Médecin scolaire : peut réaliser <span class=\"kw-clinique\">les</span> examens à partir de la <strong>6ᵉ année</strong>.</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Prise en charge</strong> — Consultations <strong>remboursées à<span class=\"kw-chiffre\"> 100 %</span></strong> par l'Assurance Maladie. Examens orientés sur <span class=\"kw-clinique\">les</span> <strong>5 axes de <span class=\"kw-def\">surveillance</span> évolutive</strong>.\n      </div>","frequence":0},{"id":"47-4","rang":"A","rubrique":"Définition","titre":"Connaître le dépistage systématique des troubles visuels","contenu":"<p>Le système visuel est <strong>immature à la naissance</strong> et son développement se poursuit jusqu'à <span class=\"kw-chiffre\">10 ans</span>. Toute perturbation peut entraîner une <span class=\"kw-alerte\">amblyopie</span>, classiquement définitive après <span class=\"kw-chiffre\">6 ans</span>.</p>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Calendrier de <span class=\"kw-def\">dépistage</span></h4>\n      <table >\n        <thead><tr><th>Population</th><th>Repères</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Âge préscolaire</strong></td><td>Naissance (maternité) · <strong>M2</strong> · <strong>M4</strong> · entre <strong>M9–M24</strong></td></tr>\n          <tr><td>Si <strong><span class=\"kw-def\">facteurs de risque</span></strong></td><td>Examen ophtalmologique avec réfraction après cycloplégie entre <strong><span class=\"kw-chiffre\">M3</span>–M12</strong></td></tr>\n          <tr><td><strong>Âge scolaire</strong></td><td><strong><span class=\"kw-chiffre\">3–4 ans</span></strong> et <strong><span class=\"kw-chiffre\">6 ans</span></strong></td></tr>\n        </tbody>\n      </table>\n\n      <p>Près de <strong><span class=\"kw-chiffre\">15–20 %</span></strong> des enfants &lt;<span class=\"kw-chiffre\"> 6 ans</span> présentent une anomalie visuelle. Le <span class=\"kw-def\">dépistage</span> systématique permet une prise en charge précoce et un <span class=\"kw-def\">pronostic</span> visuel optimal.</p>","frequence":0},{"id":"47-5","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principales situations à risque des troubles visuels","contenu":"<p><span class=\"kw-clinique\">Les</span> <strong><span class=\"kw-def\">facteurs de risque</span></strong> de troubles visuels conduisent à un examen ophtalmologique avec réfraction après cycloplégie entre <span class=\"kw-chiffre\">M3 et M12</span>.</p>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-def\">Facteurs de risque</span> reconnus</h4>\n      <ul>\n        <li><strong>Périnataux</strong> : Prématurité, RCIU, IMC (Infirmité Motrice Cérébrale), Surdité ;</li>\n        <li><strong>Neurologiques</strong> : Troubles neurologiques associés ;</li>\n        <li><strong>Génétiques / Malformatifs</strong> : Anomalies chromosomiques, Craniosténoses, Dysostoses cranio-faciales, Embryofœtopathies ;</li>\n        <li><strong>Toxiques</strong> : Exposition <em>in utero</em> à la cocaïne ou à l'<span class=\"kw-etio\">alcool</span> ;</li>\n        <li><strong>ATCD familiaux</strong> : Strabisme, troubles sévères de la réfraction, maladie ophtalmologique <span class=\"kw-etio\">héréditaire</span>.</li>\n      </ul>","frequence":0},{"id":"47-6","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les modalités du dépistage des troubles visuels par le médecin traitant","contenu":"<p>Le <span class=\"kw-def\">dépistage</span> des troubles visuels suit l'<span class=\"kw-clinique\">évolution</span> normale de la fonction visuelle. <strong>Sauf si l'acuité visuelle = 10/10</strong> à chaque œil, <span class=\"kw-clinique\">les</span> tests d'AV ne sont fiables qu'<strong>après <span class=\"kw-chiffre\">4 ans</span></strong>.</p>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Étapes de maturation et seuils d'AV</h4>\n      <table >\n        <thead><tr><th>Âge</th><th>AV</th><th>Étape clé</th></tr></thead>\n        <tbody>\n          <tr><td>Naissance</td><td><strong>1/20</strong></td><td>Fixation visage, clignement à la lumière, réflexe photomoteur</td></tr>\n          <tr><td>2–4 sem</td><td>—</td><td>Apparition réflexe de poursuite oculaire (vers <span class=\"kw-chiffre\">2 mois</span>)</td></tr>\n          <tr><td><span class=\"kw-chiffre\">2–4 mois</span></td><td><strong>1/10</strong></td><td>Clignement à la <span class=\"kw-alerte\">menace</span>, début vision couleurs, fixation, convergence</td></tr>\n          <tr><td><span class=\"kw-chiffre\">6 mois</span></td><td><strong>2/10</strong></td><td>—</td></tr>\n          <tr><td><span class=\"kw-chiffre\">1 an</span></td><td><strong>4/10</strong></td><td>—</td></tr>\n          <tr><td><span class=\"kw-chiffre\">2 ans</span></td><td><strong>6/10</strong></td><td>AV mesurable (P<span class=\"kw-chiffre\">iga</span>ssou, E de Snellen, Money)</td></tr>\n          <tr><td><span class=\"kw-chiffre\">4 ans</span></td><td><strong>10/10</strong></td><td>AV adulte atteinte</td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Tests par âge</h4>\n      <ul>\n        <li><strong>Premières semaines</strong> : réflexe photomoteur, <strong>lueur pupillaire</strong>, reflets cornéens (strabisme), poursuite oculaire horizontale ;</li>\n        <li><strong><span class=\"kw-chiffre\">4 mois</span></strong> : fixation mono/binoculaire, poursuite oculaire (nystagmus, amblyopie) ;</li>\n        <li><strong><span class=\"kw-chiffre\">9–15 mois</span></strong> : occlusion alternée (amblyopie), signe de la <strong>toupie</strong>, test de <strong>Lang</strong> (vision stéréoscopique) ;</li>\n        <li><strong><span class=\"kw-chiffre\">2,5–4 ans</span></strong> : mesure de l'AV (P<span class=\"kw-chiffre\">iga</span>ssou, Cadet) → anomalie de réfraction ;</li>\n        <li><strong><span class=\"kw-chiffre\">≥ 5 ans</span></strong> : chiffres/lettres (Cadet, échelle de Monoyer), test d'<strong>Ishihara</strong> (vision des couleurs).</li>\n      </ul>\n\n      <div class=\"callout callout-danger\">\n        <strong>À considérer comme anormal</strong> — AV &lt; 7/10 entre <span class=\"kw-chiffre\">3–4 ans</span> · différence d'AV <span class=\"kw-chiffre\">≥ 2</span>/10 entre <span class=\"kw-clinique\">les</span> 2 yeux.\n      </div>\n\n      <div class=\"callout callout-warn\">\n        <strong>Urgences ophtalmologiques pédiatriques 🚨</strong> — <span class=\"kw-alerte\">Leucocorie</span> (<span class=\"kw-etio\">rétinoblastome</span>, cataracte) · Cornée trouble · Mégalocornée · Strabisme constant · <strong>Nystagmus</strong>.\n      </div>","frequence":3,"liens":[{"href":"https://cadet-association.fr/wp-content/uploads/tests_cadet_mode_emploi.pdf","label":"CADET — Tests de dépistage visuel (PDF mode d'emploi)"}]},{"id":"47-7","rang":"A","rubrique":"Prise en charge","titre":"Connaître les indications d’adressage d’un enfant à un ophtalmologiste","contenu":"<p>Tout signe d'appel ou anomalie au <span class=\"kw-def\">dépistage</span> impose un <strong>avis ophtalmologique spécialisé</strong>.</p>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Signes d'appel par âge</h4>\n      <table >\n        <thead><tr><th>Âge</th><th>Signes</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Avant <span class=\"kw-chiffre\">4 mois</span></strong></td>\n            <td>\n              Leucocorie · Strabisme · Nystagmus · Torticolis · Signe digito-oculaire · Manque d'intérêt visuel ;<br>\n              <span class=\"kw-chiffre\">M1</span> : absence du réflexe de fixation · M3 : absence de clignement à la <span class=\"kw-alerte\">menace</span> · M4 : absence de poursuite oculaire ;<br>\n              Retard d'acquisition de la préhension (normalement vers M5).\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-chiffre\">6 mois</span> – âge verbal</strong></td>\n            <td>Indifférence à l'entourage · Enfant qui se cogne, tombe, plisse <span class=\"kw-clinique\">les</span> yeux, ferme un œil au soleil (<strong>signe de l'éventail</strong>).</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-chiffre\">2–5 ans</span></strong></td>\n            <td>Dyspraxies · Retard de langage · Lenteur d'exécution · Fat<span class=\"kw-chiffre\">iga</span>bilité.</td>\n          </tr>\n          <tr>\n            <td><strong>Enfant plus âgé</strong></td>\n            <td>Lecture trop rapprochée · <span class=\"kw-clinique\">Confusion</span> de lettres · <span class=\"kw-clinique\">Céphalées</span> · Plissements palpébraux · Rougeur, <span class=\"kw-clinique\">prurit</span> oculaire.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">\n        <strong>Urgences à adresser sans délai 🚨</strong> — <strong>Leucocorie</strong> (<span class=\"kw-etio\">rétinoblastome</span>, cataracte <span class=\"kw-etio\">congénitale</span>) · Cornée trouble · Mégalocornée · Strabisme constant · <strong>Nystagmus</strong>.\n      </div>","frequence":1},{"id":"47-8","rang":"B","rubrique":"Physiopathologie","titre":"Comprendre le développement du système visuel","contenu":"<p>Le système visuel est immature à la naissance ; son développement anatomique et fonctionnel se poursuit jusqu'à <span class=\"kw-chiffre\">10 ans</span>.</p>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Grandes étapes</h4>\n      <ul>\n        <li><strong>Naissance</strong> : AV 1/20, fixation visage à courte distance, réflexe photomoteur présent (mais amplitude/vitesse limitées) ;</li>\n        <li><strong><span class=\"kw-chiffre\">2–4 semaines</span></strong> : apparition du réflexe de poursuite oculaire (vers <span class=\"kw-chiffre\">2 mois</span>) ;</li>\n        <li><strong><span class=\"kw-chiffre\">1–2 mois</span></strong> : réflexes de fusion et de coordination binoculaire ;</li>\n        <li><strong><span class=\"kw-chiffre\">2–4 mois</span></strong> : AV 1/10, clignement à la <span class=\"kw-alerte\">menace</span>, début vision des couleurs et stéréoscopique, fixation, convergence ;</li>\n        <li><strong><span class=\"kw-chiffre\">5 mois</span></strong> : suit du regard, attrape des objets (coordination tête-œil-main) ;</li>\n        <li><strong><span class=\"kw-chiffre\">6 mois</span></strong> : AV 2/10 ;</li>\n        <li><strong><span class=\"kw-chiffre\">1 an</span></strong> : AV 4/10 ;</li>\n        <li><strong><span class=\"kw-chiffre\">2 ans</span></strong> : AV 6/10, mesurable ;</li>\n        <li><strong><span class=\"kw-chiffre\">4 ans</span></strong> : AV <strong>10/10</strong>.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Amblyopie</strong> = diminution (souvent unilatérale) de l'AV non améliorable par correction. <span class=\"kw-alerte\">Définitive après 6 ans</span> si non rééduquée — d'où l'importance du <span class=\"kw-def\">dépistage</span> précoce.\n      </div>","frequence":1},{"id":"47-9","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes fonctionnels et physiques évocateurs de malvoyance chez l’enfant","contenu":"<p>La malvoyance se révèle par des signes <strong>fonctionnels et comportementaux</strong> souvent indirects.</p>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Anomalies à rechercher</h4>\n      <ul>\n        <li><strong>Nystagmus</strong> · <strong>Strabisme</strong> ;</li>\n        <li><strong>Errance du regard</strong> ;</li>\n        <li><strong>Signe digito-oculaire</strong> (pression digitale régulière des globes oculaires) ;</li>\n        <li><strong>Indifférence visuelle</strong> lors de l'évaluation de la fixation, poursuite, préhension.</li>\n      </ul>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Causes possibles avant <span class=\"kw-chiffre\">1 an</span></h4>\n      <ul>\n        <li>Simple <strong>retard de maturation fovéolaire</strong> (résolution spontanée) ;</li>\n        <li><strong>Cécité <span class=\"kw-etio\">congénitale</span> organique</strong> : dégénérescence rétinienne · atrophie optique · cécité corticale.</li>\n      </ul>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Bilan</h4>\n      <ul>\n        <li>Bilan ophtalmologique complet (anomalie pupillaire, leucocorie...) ;</li>\n        <li><strong><span class=\"kw-imagerie\">Fond d'œil</span></strong> ;</li>\n        <li><strong>PEV</strong> (potentiels évoqués visuels) · <strong>ERG</strong> (électrorétinogramme) ;</li>\n        <li>Imagerie des voies optiques et cérébrale.</li>\n      </ul>","frequence":1,"liens":[{"href":"https://radiopaedia.org/articles/leukocoria","label":"Radiopaedia : Leucocorie"},{"href":"https://radiopaedia.org/articles/coloboma","label":"Radiopaedia : Colobome"}]},{"id":"47-10","rang":"A","rubrique":"Définition","titre":"Connaître les modalités du dépistage systématique des troubles auditifs","contenu":"<p>Environ <strong><span class=\"kw-chiffre\">5 %</span></strong> des enfants &lt;<span class=\"kw-chiffre\"> 6 ans</span> ont une anomalie auditive. L'oreille interne est mature avant la naissance : le système auditif est <strong>fonctionnel dès avant la naissance</strong>.</p>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Calendrier de <span class=\"kw-def\">dépistage</span></h4>\n      <ul>\n        <li><strong>Tous <span class=\"kw-clinique\">les</span> nouveau-nés en maternité</strong> (avec ou sans FR) : <strong>PEAA</strong> et/ou <strong>OEAP</strong> ;</li>\n        <li>Examens obl<span class=\"kw-chiffre\">iga</span>toires par le <strong>médecin traitant ou de PMI</strong> jusqu'à <strong><span class=\"kw-chiffre\">6 ans</span></strong> ;</li>\n        <li>Examens obl<span class=\"kw-chiffre\">iga</span>toires par le <strong>médecin traitant ou scolaire</strong> après <strong><span class=\"kw-chiffre\">6 ans</span></strong>.</li>\n      </ul>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Pourquoi répéter le <span class=\"kw-def\">dépistage</span> ?</h4>\n      <ul>\n        <li>Existence d'atteintes génétiques se manifestant par une <strong>surdité évolutive</strong> ;</li>\n        <li>Existence de surdités <strong>acquises après la période néonatale</strong> (ex : méningites).</li>\n      </ul>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Examens selon l'âge</h4>\n      <ul>\n        <li><strong>Maternité</strong> : OEAP et/ou PEAA ;</li>\n        <li><strong>M4</strong> : réactions aux bruits familiers ;</li>\n        <li><strong>M9</strong> : bruits familiers, réaction au prénom, <strong>boîtes à retournement</strong> ;</li>\n        <li><strong>M24</strong> : voix chuchotée et haute, jouets sonores calibrés ;</li>\n        <li><strong><span class=\"kw-chiffre\">6 ans</span></strong> : audiogramme du médecin scolaire (test de désignation + audiométrie tonale).</li>\n      </ul>","frequence":1},{"id":"47-11","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les principales situations à risque des troubles auditifs chez l’enfant en fonction de son âge","contenu":"<div class=\"callout callout-warn\">\n        ⚠️ <span class=\"kw-clinique\">Les</span> FR sont <strong>absents chez &gt;<span class=\"kw-chiffre\"> 50 %</span></strong> des surdités de perception bilatérales congénitales.\n      </div>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Facteurs familiaux</h4>\n      <ul>\n        <li>ATCD familiaux de <strong>surdité</strong> ;</li>\n        <li>ATCD familiaux de <strong>prothèse auditive avant <span class=\"kw-chiffre\">50 ans</span></strong>.</li>\n      </ul>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Anténataux</h4>\n      <ul>\n        <li>Traitement ototoxique (aminoside…) ;</li>\n        <li>Infections : <strong><span class=\"kw-etio\">CMV</span></strong>, Herpès, Rubéole, Toxoplasmose.</li>\n      </ul>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Périnataux</h4>\n      <ul>\n        <li>Grande prématurité (<strong>&lt; 32 SA</strong>), poids &lt; <strong><span class=\"kw-chiffre\">1800 g</span></strong> ;</li>\n        <li><span class=\"kw-alerte\">Asphyxie</span> périnatale, ventilation assistée <strong>&gt;<span class=\"kw-chiffre\"> 5 jours</span></strong>, hyperbilirubinémie <strong>&gt; <span class=\"kw-chiffre\">350 µmol/L</span></strong> ;</li>\n        <li>Infirmité motrice cérébrale, troubles neurologiques, malformations face et cou.</li>\n      </ul>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Postnataux (acquises)</h4>\n      <ul>\n        <li>Traumatisme crânien · Otite chronique ;</li>\n        <li>Méningites bactériennes : <span class=\"kw-etio\">pneumocoque</span>, <em><span class=\"kw-etio\">Haemophilus</span></em>, <span class=\"kw-etio\">méningocoque</span>.</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>1ères causes à retenir</strong> — Surdité <span class=\"kw-etio\">congénitale</span> non génétique : <strong><span class=\"kw-etio\">CMV</span> maternofœtal</strong> · Surdité de transmission &lt;<span class=\"kw-chiffre\"> 6 ans</span> : <strong>otite séromuqueuse</strong> · Surdité bilatérale sévère/profonde : <strong>origine <span class=\"kw-etio\">génétique</span></strong> · Surdité neurosensorielle permanente : génétique (<strong><span class=\"kw-chiffre\">80 %</span></strong>).\n      </div>","frequence":2},{"id":"47-12","rang":"B","rubrique":"Prise en charge","titre":"Connaître les modalités du dépistage des troubles auditifs par le médecin traitant","contenu":"<p>Le médecin traitant peut réaliser le <span class=\"kw-def\">dépistage</span> à tous <span class=\"kw-clinique\">les</span> âges, complété si besoin par une référence ORL.</p>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Période néonatale (maternité)</h4>\n      <ul>\n        <li><strong>OEAP</strong> (oto-émissions acoustiques provoquées) : absence = surdité (<span class=\"kw-chiffre\">5 %</span> FP) ou mauvaises conditions ;</li>\n        <li><strong>PEAA</strong> (potentiels évoqués auditifs automatisés) : stimulation à 35 dB, réponse binaire (<span class=\"kw-chiffre\">1 %</span> FP).</li>\n      </ul>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Après la période néonatale</h4>\n      <ul>\n        <li><strong>M4</strong> : étude des réactions auditives aux bruits familiers (voix, biberon, porte, prénom) ;</li>\n        <li><strong>M9</strong> : bruits familiers, réaction au prénom, <strong>boîtes à retournement</strong> (calibrées en fréquence/intensité) ;</li>\n        <li><strong>M24</strong> : voix chuchotée et haute, jouets sonores calibrés ;</li>\n        <li><strong><span class=\"kw-chiffre\">6 ans</span></strong> : audiométrie vocale (désignation mots/images) et tonale (casque, Auricheck® dès <span class=\"kw-chiffre\">3–4 ans</span>).</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Si anomalie</strong> → orientation en milieu spécialisé (ORL).\n      </div>","frequence":0},{"id":"47-13","rang":"A","rubrique":"Prise en charge","titre":"Connaître les indications d’adressage d’un enfant à un ORL","contenu":"<p>Le médecin généraliste/pédiatre adresse à l'<strong>ORL</strong> tout enfant présentant un signe d'appel auditif, un FR ou une anomalie au <span class=\"kw-def\">dépistage</span>.</p>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Signes d'appel selon l'âge</h4>\n      <table >\n        <thead><tr><th>Âge</th><th>Versant expressif</th><th>Versant réceptif</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Premiers mois</strong></td>\n            <td>Sommeil trop calme ; gazouillis à <span class=\"kw-chiffre\">M3</span> peut faire illusion mais <strong>disparaît à<span class=\"kw-chiffre\"> 1 an</span></strong>.</td>\n            <td>Enfant très observateur · Absence de réaction aux bruits · Réactions vives aux vibrations/toucher.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-chiffre\">M6</span>–M12</strong></td>\n            <td>Disparition du babillage · Absence de redoublement de syllabes.</td>\n            <td>Absence de réaction à l'appel.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-chiffre\">M12</span>–M24</strong></td>\n            <td>Pas d'association de 2 mots · Pas d'émissions vocales.</td>\n            <td>Non-réaction au prénom · Compréhension faible hors contexte.</td>\n          </tr>\n          <tr>\n            <td><strong>M24–M36</strong></td>\n            <td>Trouble massif d'articulation · Peu ou pas de phrases.</td>\n            <td>Troubles du comportement (retrait ou agitation).</td>\n          </tr>\n          <tr>\n            <td><strong>&gt;<span class=\"kw-chiffre\"> 3 ans</span></strong></td>\n            <td><strong>Tout retard de parole et de langage</strong>.</td>\n            <td>Difficultés d'apprentissage · Troubles de la concentration · Enfant hyperactif <em>ou</em> trop calme/inattentif.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Acquise</span>/secondaire</strong></td>\n            <td>Régression de l'expression · Détérioration de la parole.</td>\n            <td>Modification du comportement · Agressivité.</td>\n          </tr>\n        </tbody>\n      </table>","frequence":1},{"id":"47-14","rang":"A","rubrique":"Définition","titre":"Enfant sourd","contenu":"<h4 style=\"margin:0 0 6px;font-size:14px;color:#1f2937;\">Retentissement de la surdité selon la sévérité</h4>\n      <table >\n        <thead><tr><th>Surdité</th><th>Perte (dB)</th><th>Conséquence</th><th>Langage oral</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Légère</strong></td><td>20–40</td><td>Défaut de prononciation des consonnes · Gêne scolaire</td><td><span class=\"kw-etio\">Acquis</span> spontanément, retard possible</td></tr>\n          <tr><td><strong>Moyenne</strong></td><td>40–70</td><td>Enfant parlé tard et mal · Confusions voyelles/consonnes</td><td><span class=\"kw-etio\">Acquis</span> spontanément, retard possible</td></tr>\n          <tr><td><strong>Sévère</strong></td><td>70–90</td><td>Ne perçoit que voix forte et bruits</td><td>Non <span class=\"kw-etio\">acquis</span> spontanément · Retard majeur</td></tr>\n          <tr><td><strong>Profonde / Totale</strong></td><td><span class=\"kw-chiffre\">≥ 90</span></td><td>Aucune parole perçue</td><td>Non <span class=\"kw-etio\">acquis</span> spontanément · Retard majeur</td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Particularités de la PEC de l'enfant sourd</h4>\n      <ul>\n        <li><strong>Maintien</strong> dans son milieu familial et scolaire (possible même pour sourds profonds avec implant cochléaire précoce) ;</li>\n        <li><strong>Prise en charge pluridisciplinaire</strong> : ORL, pédiatre, pédopsychiatre, pédagogue, orthophoniste, audioprothésiste ;</li>\n        <li>Surdités de transmission : traitement médical/chirurgical ;</li>\n        <li><strong>Appareillage le plus précoce possible</strong> si surdité moyenne à profonde (dès <span class=\"kw-clinique\">les</span> premiers mois de vie) ;</li>\n        <li><strong>PEC orthophonique systématique</strong> (accompagne <span class=\"kw-clinique\">les</span> parents, éducation auditive, développement du langage oral) ;</li>\n        <li><strong>Langue des signes</strong> proposée si choix parental ou surdité profonde bilatérale sans réhabilitation auditive efficace possible.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Risque principal</strong> de la surdité chez l'enfant = <span class=\"kw-alerte\">trouble de la communication orale</span>, surtout si surdité <strong>bilatérale et importante</strong> ou surdité <strong>avant <span class=\"kw-chiffre\">18 mois</span>–<span class=\"kw-chiffre\">2 ans</span></strong>.\n      </div>","frequence":0},{"id":"47-15","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les principes de mesure de l’audition chez l’enfant","contenu":"<h4 style=\"margin:0 0 6px;font-size:14px;color:#1f2937;\">Audiométrie objective (à tout âge)</h4>\n      <ul>\n        <li><strong>PEAP</strong> (potentiels évoqués auditifs précoces) ;</li>\n        <li><strong>OEAP</strong> (oto-émissions acoustiques provoquées) ;</li>\n        <li><strong>ASSR</strong> (Auditory Steady State Response) pour <span class=\"kw-clinique\">les</span> seuils auditifs.</li>\n      </ul>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Audiométrie subjective selon l'âge</h4>\n      <table >\n        <thead><tr><th>Âge</th><th>Méthode</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>&lt;<span class=\"kw-chiffre\"> 10 mois</span></strong></td>\n            <td><strong>Audiométrie comportementale</strong> — observation des réactions aux stimuli (arrêt de la tétée…). Courbe auditive de la meilleure oreille.</td>\n          </tr>\n          <tr>\n            <td><strong>M10 –<span class=\"kw-chiffre\"> 5 ans</span></strong></td>\n            <td>\n              <strong>Audiométrie par réflexe conditionné</strong> (ORL) :\n              <ul>\n                <li><strong>ROC</strong> (Réflexe d'Orientation Conditionné) dès <strong><span class=\"kw-chiffre\">1 an</span></strong> — enfant tourne la tête vers la source sonore ;</li>\n                <li><strong>Train show / Peep show</strong> (Auricheck®) entre <strong><span class=\"kw-chiffre\">3–5 ans</span></strong> — enfant appuie sur un bouton mettant en marche un train ou une image ;</li>\n                <li>Audiogramme précis à <strong>10–15 dB près</strong> pour toutes <span class=\"kw-clinique\">les</span> fréquences.</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>&gt;<span class=\"kw-chiffre\"> 5 ans</span></strong></td>\n            <td>Audiométrie tonale et vocale classiques de l'adulte.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Confirmation systématique</strong> par <strong>épreuves objectives</strong> (PEA + ASSR), même chez l'enfant verbal.\n      </div>","frequence":0},{"id":"47-16","rang":"A","rubrique":"Définition","titre":"Connaître la numérotation dentaire internationale","contenu":"<p>La <strong>FDI</strong> (Fédération Dentaire Internationale) numérote <span class=\"kw-clinique\">les</span> dents par <strong>quadrants</strong>, dans le sens horaire vu de face.</p>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Adulte (32 dents)</h4>\n      <table >\n        <thead><tr><th>Quadrant</th><th>Code</th><th>Dents</th></tr></thead>\n        <tbody>\n          <tr><td>Maxillaire droit</td><td><strong>1</strong></td><td>11–18</td></tr>\n          <tr><td>Maxillaire gauche</td><td><strong>2</strong></td><td>21–28</td></tr>\n          <tr><td>Mandibulaire gauche</td><td><strong>3</strong></td><td>31–38</td></tr>\n          <tr><td>Mandibulaire droit</td><td><strong>4</strong></td><td>41–48</td></tr>\n        </tbody>\n      </table>\n      <p>Soit <strong>8 dents par quadrant</strong> : incisive centrale (1) · latérale (2) · canine (3) · 1ʳᵉ prémolaire (4) · 2ᵉ prémolaire (5) · 1ʳᵉ molaire (6) · 2ᵉ molaire (7) · 3ᵉ molaire (8).</p>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Enfant (20 dents temporaires)</h4>\n      <table >\n        <thead><tr><th>Quadrant</th><th>Code</th><th>Dents</th></tr></thead>\n        <tbody>\n          <tr><td>Maxillaire droit</td><td><strong>5</strong></td><td>51–55</td></tr>\n          <tr><td>Maxillaire gauche</td><td><strong>6</strong></td><td>61–65</td></tr>\n          <tr><td>Mandibulaire gauche</td><td><strong>7</strong></td><td>71–75</td></tr>\n          <tr><td>Mandibulaire droit</td><td><strong>8</strong></td><td>81–85</td></tr>\n        </tbody>\n      </table>\n      <p>Soit <strong>5 dents par hémi-arcade</strong> en denture temporaire : 8 incisives, 4 canines, 8 molaires (pas de prémolaires).</p>","frequence":3,"liens":[{"href":"https://radiopaedia.org/articles/federation-dentaire-internationale-fdi-notation","label":"Radiopaedia : FDI notation (numérotation dentaire)"}]},{"id":"47-17","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’une carie dentaire","contenu":"<p>La carie est une <strong>protéolyse microbienne de l'émail et de la dentine</strong>, souvent due à <em>Streptococcus mutans</em>.</p>\n\n      <ul>\n        <li>Pathologie liée au développement et à la <strong>stagnation de la <span class=\"kw-clinique\">plaque</span> dentaire</strong> ;</li>\n        <li>L'une des pathologies <span class=\"kw-clinique\">les</span> plus fréquentes au monde ;</li>\n        <li>Germes pathogènes opportunistes en conditions favorisantes : <em>Streptococcus</em>, <em>Peptostreptococcus</em>, <em><span class=\"kw-etio\">Bacteroides</span></em> ;</li>\n        <li><strong>Carie précoce de la petite enfance</strong> = maladie carieuse limitée aux dents temporaires.</li>\n      </ul>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Stades cliniques</h4>\n      <ol>\n        <li><strong>Déminéralisation</strong> aspect crayeux, sans cavitation (lésions amélaires <strong>reminéralisables</strong>) ;</li>\n        <li><strong>Cavitation</strong> de l'émail si absence de PEC ;</li>\n        <li><strong>Dentinite</strong> : douleur provoquée par froid/chaud/sucré/acide · rugosité, ramollissement dentinaire au sondage.</li>\n      </ol>\n\n      <div class=\"callout callout-danger\">\n        <strong>Signes d'alerte</strong> ⚠️ — <strong>Douleurs spontanées</strong> · Complications possibles : pulpite aiguë · desmodontite · <span class=\"kw-clinique\">cellulite</span> · <span class=\"kw-clinique\">abcès</span>.\n      </div>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/dental-caries","label":"Radiopaedia : Dental caries"}]},{"id":"47-18","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de prévention de la carie dentaire","contenu":"<p>La PEC de la carie relève du <strong>chirurgien-dentiste</strong>, mais sa prévention incombe à <strong>tout médecin</strong>.</p>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">4 mesures préventives</h4>\n      <ul>\n        <li><strong>Brossage 2×/jour</strong> dès l'apparition des dents (<span class=\"kw-chiffre\">6 mois</span>), avec <strong>dentifrice fluoré</strong> adapté à l'âge :\n          <ul><li>Brossage <strong>post-prandial réalisé par <span class=\"kw-clinique\">les</span> parents jusqu'à<span class=\"kw-chiffre\"> 6 ans</span></strong>, puis selon l'autonomie.</li></ul>\n        </li>\n        <li><strong>Hygiène alimentaire</strong> : limiter grignotages sucrés hors repas, pas de biberon sucré/lait à l'endormissement ;</li>\n        <li><strong>Scellement / comblement des sillons</strong> des 1ʳᵉˢ et 2ᵉˢ molaires définitives saines ;</li>\n        <li><strong>Fluorures systémiques</strong> seulement si <strong>risque carieux élevé</strong>, <strong>non recommandés avant <span class=\"kw-chiffre\">6 mois</span></strong> (max <span class=\"kw-chiffre\">1 mg</span>/jour tous apports confondus — risque de <strong>fluorose</strong>).</li>\n      </ul>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Consultations spécialisées</h4>\n      <ul>\n        <li>1ʳᵉ consultation chez le dentiste <strong>entre 12 et <span class=\"kw-chiffre\">18 mois</span></strong> ;</li>\n        <li>Visites <strong>« M'T dents »</strong> recommandées et prises en charge à partir de <span class=\"kw-chiffre\">3 ans</span>, tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">3 ans</span> (jusqu'à<span class=\"kw-chiffre\"> 24 ans</span>) ;</li>\n        <li><strong>5 examens bucco-dentaires</strong> entre 3 et <span class=\"kw-chiffre\">16 ans</span> pris en charge à<span class=\"kw-chiffre\"> 100 %</span>.</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Mécanisme du fluor</strong> — inhibe la production d'acides bactériens, accélère la reminéralisation, transforme l'émail en <strong>fluoroapatite</strong> (plus résistante aux attaques acides que l'hydroxyapatite).\n      </div>","frequence":1},{"id":"47-19","rang":"B","rubrique":"Physiopathologie","titre":"Connaître le calendrier d’éruption dentaire","contenu":"<h4 style=\"margin:0 0 6px;font-size:14px;color:#1f2937;\">Dentition temporaire — entre <span class=\"kw-chiffre\">M6</span> et M30 (20 dents)</h4>\n      <table >\n        <thead><tr><th>Âge</th><th>Dent</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-chiffre\">M6</span></strong></td><td>Incisive <strong>centrale</strong></td></tr>\n          <tr><td><strong>M9</strong></td><td>Incisive <strong>latérale</strong></td></tr>\n          <tr><td><strong><span class=\"kw-chiffre\">M12</span></strong></td><td>1ʳᵉ molaire</td></tr>\n          <tr><td><strong>M18</strong></td><td>Canine</td></tr>\n          <tr><td><strong>M24</strong></td><td>2ᵉ molaire</td></tr>\n        </tbody>\n      </table>\n      <p><em>La 1ʳᵉ molaire sort avant la 1ʳᵉ canine.</em> Plus précoce chez la fille, à la mandibule. Symétrique sur chaque hémi-arcade (décalage de quelques mois possible).</p>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Dentition définitive — entre <span class=\"kw-chiffre\">6 ans</span> et <span class=\"kw-chiffre\">18 ans</span> (32 dents)</h4>\n      <table >\n        <thead><tr><th>Âge</th><th>Dent</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-chiffre\">6 ans</span></strong></td><td>1ʳᵉ molaire (1ʳᵉ dent définitive)</td></tr>\n          <tr><td><strong><span class=\"kw-chiffre\">7 ans</span></strong></td><td>Incisive <strong>centrale</strong></td></tr>\n          <tr><td><strong><span class=\"kw-chiffre\">8 ans</span></strong></td><td>Incisive <strong>latérale</strong></td></tr>\n          <tr><td><strong><span class=\"kw-chiffre\">9 ans</span></strong></td><td>1ʳᵉ prémolaire</td></tr>\n          <tr><td><strong><span class=\"kw-chiffre\">10 ans</span></strong></td><td>Canine</td></tr>\n          <tr><td><strong><span class=\"kw-chiffre\">11 ans</span></strong></td><td>2ᵉ prémolaire</td></tr>\n          <tr><td><strong><span class=\"kw-chiffre\">12 ans</span></strong></td><td>2ᵉ molaire</td></tr>\n          <tr><td><strong><span class=\"kw-chiffre\">18 ans</span></strong></td><td>3ᵉ molaire (« dent de sagesse »)</td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Anomalies d'<span class=\"kw-clinique\">éruption</span></h4>\n      <ul>\n        <li><strong>Retard temporaire</strong> : ≥ <strong><span class=\"kw-chiffre\">6 mois</span></strong> de décalage ;</li>\n        <li><strong>Retard permanent</strong> : &gt; <strong><span class=\"kw-chiffre\">1 an</span></strong> de décalage ; rechercher agénésie (radio), maladie générale, dent <strong>incluse</strong> (trajet normal) ou <strong>ectopique</strong> (hors trajet) ;</li>\n        <li><strong><span class=\"kw-clinique\">Éruption</span> précoce</strong> : rare, souvent due à la perte prématurée d'une dent temporaire.</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Stades</strong> — Dentition déciduale complète à <strong><span class=\"kw-chiffre\">30 mois</span></strong> · Dentition <strong>mixte</strong> dès <strong><span class=\"kw-chiffre\">6 ans</span></strong> · Dentition <strong>définitive</strong> à partir de <strong><span class=\"kw-chiffre\">12 ans</span></strong>.\n      </div>","frequence":2},{"id":"47-20","rang":"B","rubrique":"Définition","titre":"Savoir identifier un trouble de l’articulé dentaire","contenu":"<p><strong>Articulé dentaire</strong> = rapports entre <span class=\"kw-clinique\">les</span> dents maxillaires et mandibulaires. <strong>Trouble de l'articulé</strong> = conflit entre les 2 arcades. Examen en <strong>occlusion d'intercuspidation maximale</strong>.</p>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Troubles en denture temporaire</h4>\n      <ul>\n        <li>Latérodéviation mandibulaire · Prognathie mandibulaire · Bout-à-bout des incisives ;</li>\n        <li><strong>Béance</strong> (trace de succion tétine/pouce) ;</li>\n        <li><strong>Absence d'espace</strong> entre incisive-canine au maxillaire · entre canine-1ʳᵉ molaire à la mandibule ;</li>\n        <li>Anomalie du nombre des dents perturbant l'articulé.</li>\n      </ul>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Troubles en denture mixte et permanente</h4>\n      <ul>\n        <li>Latérodéviation mandibulaire · Prognathie mandibulaire · Bout-à-bout ;</li>\n        <li><strong>Pro-alvéolie maxillaire</strong> ;</li>\n        <li><strong>Encombrement</strong> (chevauchement) ;</li>\n        <li>Anomalie du nombre des dents.</li>\n      </ul>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-def\">Classification</span> d'Angle (plan sagittal)</h4>\n      <table >\n        <thead><tr><th>Classe</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Angle I</strong></td><td>Articulé normal : 1ʳᵉ molaire/canine inférieures en avant d'une demi-dent par rapport aux supérieures</td></tr>\n          <tr><td><strong>Angle II</strong></td><td>Denture inférieure plus en arrière (rétromandibulie, promaxillie, rétro-alvéolie mandibulaire, pro-alvéolie maxillaire)</td></tr>\n          <tr><td><strong>Angle III</strong></td><td>Denture inférieure plus en avant (promandibulie, rétromaxillie, pro-alvéolie mandibulaire, rétro-alvéolie maxillaire)</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>CAT</strong> — Prise en charge rapide par un <strong>orthodontiste avant <span class=\"kw-chiffre\">16 ans</span></strong>.\n      </div>","frequence":1},{"id":"47-21","rang":"A","rubrique":"Diagnostic positif","titre":"Luxation congénitale de Hanche : connaître l’indication du dépistage","contenu":"<p>La LCH résulte d'une anomalie anténatale de la hanche (conflit contenant/contenu) ; à la naissance, la hanche est instable et peut se stabiliser ou se luxer dans <span class=\"kw-clinique\">les</span> premières semaines, <strong>en l'absence de traitement</strong>.</p>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Indications du <span class=\"kw-def\">dépistage</span></h4>\n      <ul>\n        <li><strong>Tout nouveau-né</strong> doit faire l'objet d'un <span class=\"kw-def\">dépistage</span> clinique à la naissance ;</li>\n        <li><span class=\"kw-def\">Dépistage</span> <strong>répété à chaque consultation médicale jusqu'à l'âge de la marche</strong>.</li>\n      </ul>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-def\">Facteurs de risque</span> (renforcent la vigilance, <span class=\"kw-def\">dépistage</span> obl<span class=\"kw-chiffre\">iga</span>toire dans tous <span class=\"kw-clinique\">les</span> cas)</h4>\n      <ul>\n        <li><strong>ATCD familiaux de LCH au 1ᵉʳ degré</strong> (diagnostic confirmé) ;</li>\n        <li><strong>Présentation en siège</strong> (y compris version tardive), quel que soit le mode d'accouchement.</li>\n      </ul>\n      <p>FR secondaires (augmentent la vigilance sans augmentation réelle d'<span class=\"kw-def\">incidence</span>) : bassin asymétrique <span class=\"kw-etio\">congénital</span> · anomalies posturales (<strong>genu recurvatum</strong>, <strong>torticolis</strong>, déformations des pieds).</p>\n\n      <div class=\"callout callout-warn\">\n        <strong><span class=\"kw-def\">Épidémiologie</span></strong> — Fréquence : <strong>3–4/1000</strong> · Sex-ratio : <strong>4F/<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>1</span>G</span></strong>. L'absence de FR ou la normalité des examens antérieurs <strong>ne dispense pas du <span class=\"kw-def\">dépistage</span></strong>.\n      </div>\n\n      <div class=\"callout callout-info\">\n        <strong>Pourquoi dépister</strong> — Guérison complète si PEC ambulatoire dans <span class=\"kw-clinique\">les</span> <strong>5 premières semaines</strong> · Plus l'enfant est âgé, plus la PEC se complique avec risque de séquelles · Diagnostic après <span class=\"kw-chiffre\">3 mois</span> nécessite en moyenne <strong><span class=\"kw-chiffre\">20 jours</span> d'<span class=\"kw-alerte\">hospitalisation</span></strong>.\n      </div>","frequence":0},{"id":"47-22","rang":"A","rubrique":"Diagnostic positif","titre":"Luxation congénitale de Hanche : connaître les modalités du dépistage","contenu":"<p>Examen sur un enfant <strong>relâché et calmé</strong> ; si tonique, répéter quelques heures plus tard. Recherche de <strong>2 signes</strong>.</p>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">1. Limitation de l'abduction</h4>\n      <ul>\n        <li>Nourrisson couché sur le dos, hanches fléchies à 90° ;</li>\n        <li><strong>Normal</strong> : abduction <strong><span class=\"kw-chiffre\">≥ 60</span>°</strong> pour chaque hanche ;</li>\n        <li><strong>Limitation</strong> du <strong>volant d'abduction &lt; 60°</strong> = FR très important → imagerie ± orthopédiste pédiatre.</li>\n      </ul>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">2. Instabilité de la hanche — Manœuvre de Barlow</h4>\n      <p>Ressaut = signe <strong>pathognomonique</strong>. Technique la plus sensible :</p>\n      <ol>\n        <li><strong>Le Damany-Ortolani</strong> : hanche en <strong>adduction</strong>, <strong>rotation externe</strong>, pression axiale sur le genou :\n          <ul>\n            <li>Normal : sensation de « <strong>piston</strong> » ;</li>\n            <li>Pathologique : <strong>ressaut de luxation</strong> (franchissement par la tête fémorale du rebord cotyloïdien).</li>\n          </ul>\n        </li>\n        <li><strong>BARLOW</strong> (2ᵉ temps) : hanche en <strong>abduction</strong>, <strong>rotation interne</strong>, <strong>traction axiale + pression sur le grand trochanter</strong> :\n          <ul><li><strong>Ressaut de <span class=\"kw-ttt\">réduction</span></strong> = franchissement inverse (retour de la tête dans le cotyle).</li></ul>\n        </li>\n      </ol>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Interprétation</h4>\n      <table >\n        <thead><tr><th>État</th><th>Ressaut luxation</th><th>Ressaut <span class=\"kw-ttt\">réduction</span></th></tr></thead>\n        <tbody>\n          <tr><td><strong>Luxable</strong> (en place spontanément)</td><td>Perçu</td><td>Perçu</td></tr>\n          <tr><td><strong>Luxée réductible</strong></td><td>Non</td><td>Perçu</td></tr>\n          <tr><td><strong>Luxée irréductible</strong></td><td>Non · pas de bruit de piston</td><td>Non</td></tr>\n          <tr><td><em>Normal</em></td><td><em>Bruit de piston</em></td><td><em>Non</em></td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"47-23","rang":"B","rubrique":"Diagnostic positif","titre":"Luxation congénitale de Hanche : connaître les formes cliniques","contenu":"<p>3 formes cliniques peuvent être identifiées au <span class=\"kw-def\">dépistage</span> par <span class=\"kw-clinique\">les</span> manœuvres de Barlow et Ortolani :</p>\n\n      <table >\n        <thead><tr><th>Forme</th><th>Description clinique</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Hanche luxable</strong></td>\n            <td>Hanche <strong>en place spontanément</strong> mais instable. Ressaut de <strong>luxation</strong> et de <strong><span class=\"kw-ttt\">réduction</span></strong> tous deux perçus.</td>\n          </tr>\n          <tr>\n            <td><strong>Hanche luxée réductible</strong></td>\n            <td>Hanche <strong>luxée au repos</strong>, mais réductible par la manœuvre de Barlow. Ressaut de <strong><span class=\"kw-ttt\">réduction</span></strong> perçu (entrée dans le cotyle), pas de ressaut de luxation.</td>\n          </tr>\n          <tr>\n            <td><strong>Hanche luxée irréductible</strong></td>\n            <td>Hanche <strong>luxée non réductible</strong>. Aucun ressaut, ni bruit de piston (forme la plus tardive et grave).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong><span class=\"kw-def\">Diagnostic différentiel</span></strong> — Limitation de l'abduction par hypertonie des adducteurs (forme ancienne du référentiel).\n      </div>","frequence":0},{"id":"47-24","rang":"B","rubrique":"Examens complémentaires","titre":"Luxation congénitale de Hanche : connaître l’indication de l’imagerie","contenu":"<div class=\"callout callout-info\">\n        <strong>📌 Pivot</strong> — L'examen clinique reste la <strong>seule méthode de <span class=\"kw-def\">dépistage</span></strong> de la LCH. L'imagerie n'est pas une technique de dépistage.\n      </div>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Indications d'imagerie</h4>\n      <ul>\n        <li><strong>Anomalie</strong> à l'examen clinique ;</li>\n        <li>Présence de <strong><span class=\"kw-def\">facteurs de risque</span></strong>.</li>\n      </ul>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Choix de l'imagerie selon l'âge</h4>\n      <table >\n        <thead><tr><th>Âge</th><th>Imagerie</th></tr></thead>\n        <tbody>\n          <tr><td><strong>&lt;<span class=\"kw-chiffre\"> 4 mois</span></strong> (avant noyaux épiphysaires)</td><td><strong><span class=\"kw-imagerie\">Échographie</span></strong> (examen de choix)</td></tr>\n          <tr><td><strong><span class=\"kw-chiffre\">≥ 4 mois</span></strong> (après apparition noyaux)</td><td><strong><span class=\"kw-imagerie\">Radiographie</span></strong></td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">\n        🔥 Toute anomalie à l'imagerie requiert une <strong>prise en charge spécialisée</strong>.\n      </div>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Algorithme de <span class=\"kw-def\">dépistage</span></h4>\n      <ul>\n        <li><strong>Examen clinique normal + sans FR</strong> → <span class=\"kw-def\">suivi</span> habituel ;</li>\n        <li><strong>Examen clinique normal + FR</strong> (siège, ATCD 1ᵉʳ degré, autres anomalies ortho) → <strong><span class=\"kw-imagerie\">échographie</span> à<span class=\"kw-chiffre\"> 1 mois</span> + avis spécialisé</strong> ;</li>\n        <li><strong>Examen clinique anormal</strong> → <strong><span class=\"kw-imagerie\">échographie</span> précoce + avis spécialisé</strong>.</li>\n      </ul>","frequence":0},{"id":"47-25","rang":"B","rubrique":"Pronostic Suivi évolutif","titre":"Luxation congénitale de Hanche : connaître les complications","contenu":"<p>Le <span class=\"kw-def\">pronostic</span> dépend de la <strong>précocité de la PEC</strong>. Plus l'enfant est âgé, plus la prise en charge devient complexe avec des risques croissants de séquelles anatomiques.</p>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-clinique\">Évolution</span> selon la PEC</h4>\n      <ul>\n        <li><strong>PEC ambulatoire dans <span class=\"kw-clinique\">les</span> 5 premières semaines de vie</strong> : guérison <strong>complète et sans séquelles</strong> ;</li>\n        <li><strong>Diagnostic après <span class=\"kw-chiffre\">3 mois</span></strong> : nécessite en moyenne <strong><span class=\"kw-chiffre\">20 jours</span> d'<span class=\"kw-alerte\">hospitalisation</span></strong> ;</li>\n        <li><strong>Diagnostic tardif</strong> : risques croissants de séquelles anatomiques.</li>\n      </ul>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Complications potentielles</h4>\n      <ul>\n        <li><strong>Séquelles anatomiques</strong> de la hanche (dysplasie résiduelle) ;</li>\n        <li><strong>Boiterie</strong>, <span class=\"kw-clinique\">asymétrie</span> de longueur des membres inférieurs ;</li>\n        <li><strong>Coxarthrose précoce</strong> à l'âge adulte ;</li>\n        <li><strong><span class=\"kw-clinique\">Nécrose</span></strong> de la tête fémorale (complication du traitement orthopédique) ;</li>\n        <li>Retentissement fonctionnel sur la marche et la pratique sportive.</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        Coût élevé de la PEC tardive : <span class=\"kw-alerte\">hospitalisation</span> prolongée et <span class=\"kw-ttt\">chirurgie</span> souvent nécessaires.\n      </div>","frequence":0},{"id":"47-26","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic des anomalies d’axe des membres inférieurs","contenu":"<p>L'<strong>ontogenèse</strong> (<span class=\"kw-clinique\">évolution</span> de l'anatomie) explique qu'une situation normale à un âge soit pathologique à un autre. <span class=\"kw-clinique\">Les</span> axes sont étudiés dans les plans transversal (troubles rotationnels) et frontal.</p>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Plan transversal — troubles rotationnels</h4>\n      <ul>\n        <li><strong>Antétorsion fémorale</strong> : 35–40° à la naissance → 10–15° à maturité (diminue de 1–2°/an) ;</li>\n        <li><strong>Torsion tibiale externe</strong> : nulle à la naissance → 30° en fin de croissance ;</li>\n        <li>Examen : marche (pied dirigé en dehors 10–20°), rotations en décubitus dorsal jambes pendantes, <strong>manœuvre de Netter</strong> en décubitus ventral ;</li>\n        <li>Conséquences : marche en rotation interne (chutes répétées) chez le jeune enfant ; marche en rotation externe chez le plus grand.</li>\n      </ul>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Plan frontal — Genu varum / valgum</h4>\n      <ul>\n        <li><strong>Genu varum</strong> : distance intercondylienne (DIC) &gt;<span class=\"kw-chiffre\"> 0 cm</span> ;</li>\n        <li><strong>Genu valgum</strong> : distance intermalléolaire (DIM) &gt;<span class=\"kw-chiffre\"> 0 cm</span> ;</li>\n        <li><strong>Naissance –<span class=\"kw-chiffre\"> 3 ans</span></strong> : genu <strong>varum</strong> (s'annule entre <span class=\"kw-chiffre\">18 mois</span> et <span class=\"kw-chiffre\">3 ans</span>) ;</li>\n        <li><strong><span class=\"kw-chiffre\">3–10 ans</span></strong> : genu <strong>valgum</strong> (max à<span class=\"kw-chiffre\"> 3 ans</span> fille,<span class=\"kw-chiffre\"> 4 ans</span> garçon, diminue jusqu'à puberté) ;</li>\n        <li><strong>Puberté</strong> : alignement (filles léger valgum, garçons tendent vers varum).</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Situations pathologiques imposant radiographies + avis spécialisé</strong>\n        <ul>\n          <li>Déformations <strong>en dehors des âges normaux</strong> ;</li>\n          <li>Déformations <strong>très accentuées</strong> ;</li>\n          <li>Déformation <strong>asymétrique</strong> (quel que soit l'âge) ;</li>\n          <li>Déformation <strong>douloureuse</strong> (quel que soit l'âge).</li>\n        </ul>\n      </div>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Étiologies potentielles</h4>\n      <ul>\n        <li><strong><span class=\"kw-etio\">Rachitisme</span></strong> (vitamino-résistant en France) → genu varum ;</li>\n        <li><strong>Maladie de <span class=\"kw-etio\">Blount</span></strong> → genu varum uni/bilatéral ;</li>\n        <li>Maladie osseuse constitutionnelle (<span class=\"kw-etio\">achondroplasie</span>, dysplasie polyépiphysaire) → petite taille + varum/valgum.</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>CAT troubles rotationnels</strong> — Aucun traitement orthopédique (rééducation, attelles, semelles) n'est efficace. Correction <strong>chirurgicale</strong> réservée aux formes majeures.\n      </div>","frequence":0},{"id":"47-27","rang":"A","rubrique":"Diagnostic positif","titre":"Scoliose de l’enfant : connaître les facteurs de risque","contenu":"<p>La scoliose = <strong>déformation du rachis dans <span class=\"kw-clinique\">les</span> 3 plans de l'espace</strong> (frontal, sagittal, horizontal). Diagnostic = mise en évidence de la <strong>gibbosité</strong> (pathognomonique de la scoliose structurale).</p>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Étiologies</h4>\n      <ul>\n        <li><strong>Scoliose idiopathique</strong> (&gt; <strong><span class=\"kw-chiffre\">80 %</span></strong>) — indolore, prédominance féminine (<strong><span class=\"kw-chiffre\">80 %</span></strong>), <span class=\"kw-def\">dépistage</span> à l'<strong>adolescence</strong> ;</li>\n        <li>Scoliose <strong>neuromusculaire</strong> ;</li>\n        <li>Scoliose <strong>malformative</strong> dite <span class=\"kw-etio\">congénitale</span> ;</li>\n        <li>Scoliose <strong>dystrophique</strong> de la <span class=\"kw-etio\">neurofibromatose</span> ;</li>\n        <li>Maladie de <strong><span class=\"kw-etio\">Marfan</span></strong>.</li>\n      </ul>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-def\">Facteurs de risque</span> d'aggravation</h4>\n      <ul>\n        <li><strong>Croissance staturale rapide</strong> — risque maximum en <strong>période pubertaire</strong> ;</li>\n        <li>Sexe <strong>féminin</strong> (idiopathique) ;</li>\n        <li>Angle de <strong>Cobb élevé</strong> au diagnostic.</li>\n      </ul>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Conséquences si scoliose &gt; 30°</h4>\n      <ul>\n        <li>Douleurs précoces à l'âge adulte ;</li>\n        <li>Troubles respiratoires (diminution <span class=\"kw-bio\">capacité vitale</span>, <span class=\"kw-bio\">VEMS</span>) ;</li>\n        <li>Troubles psychologiques liés à la « mal tolérance » de l'aspect dysmorphique.</li>\n      </ul>","frequence":0},{"id":"47-28","rang":"A","rubrique":"Diagnostic positif","titre":"Scoliose de l’enfant : connaître l’examen clinique","contenu":"<p>Enfant examiné <strong>debout</strong> de face, de profil, de dos et en <strong>antéflexion</strong>.</p>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Mise en évidence de la gibbosité (diagnostic)</h4>\n      <ol>\n        <li>Examinateur assis, place l'enfant devant lui debout de face/dos ;</li>\n        <li>Vérification du bon <strong>équilibre du bassin</strong> (épines iliaques antérosupérieures de face ou fossettes iliaques de dos) ;</li>\n        <li>Mains de l'enfant jointes pour équilibrer <span class=\"kw-clinique\">les</span> épaules, puis <strong>antéflexion du tronc</strong> mains jointes vers les pieds ;</li>\n        <li>La gibbosité apparaît du côté <strong>convexe</strong> de la courbure (rotation vertébrale entraînant <span class=\"kw-clinique\">les</span> côtes en arrière).</li>\n      </ol>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Autres éléments cliniques</h4>\n      <ul>\n        <li>Déséquilibre de hauteur des épaules ;</li>\n        <li>Saillie asymétrique des scapulas, déviation de la ligne des épineuses ;</li>\n        <li>Déséquilibre du tronc, <span class=\"kw-clinique\">asymétrie</span> des plis de la taille ;</li>\n        <li><strong><span class=\"kw-def\">Stade</span> pubertaire (Tanner)</strong> et <strong>maturité osseuse (test de Risser)</strong>.</li>\n      </ul>\n\n      <div class=\"callout callout-danger\">\n        🚩 <strong>Rechercher une étiologie</strong> avant d'affirmer une scoliose idiopathique\n        <ul>\n          <li>Maladie de <strong><span class=\"kw-etio\">Marfan</span></strong> : hyperlaxité tissulaire ;</li>\n          <li><strong><span class=\"kw-etio\">Neurofibromatose</span></strong> : taches café-au-lait ;</li>\n          <li>Malformation vertébrale : <strong>angiome</strong> ou <strong>touffe pileuse</strong> sur la ligne médiane ;</li>\n          <li>Anomalies neurologiques : <span class=\"kw-clinique\">asymétrie</span> tonus/ROT, abolition des réflexes cutanés abdominaux.</li>\n        </ul>\n      </div>\n\n      <div class=\"callout callout-warn\">\n        <strong><span class=\"kw-def\">Diagnostic différentiel</span> — Attitude scoliotique</strong> (n'est pas une scoliose) : bassin équilibré · pas de rotation vertébrale · <strong>disparition de la déviation en décubitus</strong>.\n      </div>","frequence":1},{"id":"47-29","rang":"B","rubrique":"Examens complémentaires","titre":"Scoliose de l’enfant : connaître l’indication de l’imagerie","contenu":"<h4 style=\"margin:0 0 6px;font-size:14px;color:#1f2937;\">1ᵉʳ bilan</h4>\n      <ul>\n        <li><strong><span class=\"kw-imagerie\">Radiographie</span> du rachis en entier</strong>, <strong>de dos</strong> et <strong>de profil</strong>, en <strong>position debout</strong>.</li>\n      </ul>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Analyse en plan frontal (rachis entier de dos)</h4>\n      <ul>\n        <li><strong>Angle de Cobb</strong> = défini par <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>2</span> l</span>ignes parallèles aux 2 plateaux vertébraux les plus inclinés par rapport à l'horizontale (<span class=\"kw-def\">suivi</span> de l'évolutivité) ;</li>\n        <li>Localisations : <strong>lordoscoliose</strong> (majorité) · cyphoscoliose (exceptionnelle) · scoliose double.</li>\n      </ul>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Cliché de profil</h4>\n      <ul>\n        <li>Met en évidence <span class=\"kw-clinique\">les</span> courbures sagittales ;</li>\n        <li><strong>Non nécessairement répété</strong> au cours de la <span class=\"kw-def\">surveillance</span>.</li>\n      </ul>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-def\">Suivi</span></h4>\n      <ul>\n        <li><strong>Technique EOS</strong> = imagerie <strong>moins irradiante</strong>, idéale dans le cadre du <span class=\"kw-def\">suivi</span> ;</li>\n        <li>Cliché de profil non nécessaire au <span class=\"kw-def\">suivi</span>.</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>PEC selon Cobb</strong>\n        <ul>\n          <li><strong>&lt; 15°</strong> + croissance : <span class=\"kw-def\">réévaluation</span> clinique/radiologique <strong>semestrielle</strong>, espacée progressivement ;</li>\n          <li><strong>Évolutivité</strong> : avis orthopédiste pédiatre (corset · kiné · arthrodèse vertébrale si formes sévères).</li>\n        </ul>\n      </div>","frequence":0},{"id":"47-30","rang":"B","rubrique":"Contenu multimédia","titre":"Radiographie du rachis lombaire d’une scoliose malformative","contenu":"<p>Une scoliose malformative (dite <span class=\"kw-etio\">congénitale</span>) est causée par une <strong>anomalie de la formation ou de la segmentation des vertèbres</strong> in utero.</p>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">À reconnaître sur la <span class=\"kw-imagerie\">radiographie</span></h4>\n      <ul>\n        <li><strong>Hémivertèbre</strong> (anomalie de formation) — vertèbre triangulaire ou en coin ;</li>\n        <li><strong>Barre vertébrale unilatérale</strong> (anomalie de segmentation) — fusion partielle entre 2 vertèbres ;</li>\n        <li><strong>Vertèbre en bloc</strong> — fusion complète de 2 vertèbres ou plus ;</li>\n        <li><strong><span class=\"kw-clinique\">Asymétrie</span> des pédicules</strong> et déformation associée du rachis ;</li>\n        <li>Courbure souvent <strong>court rayon, angulaire</strong>, contrastant avec la courbure douce de la scoliose idiopathique.</li>\n      </ul>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/47/rp-rachis-scoliose-malformative.png\" alt=\"Radiographie du rachis en totalité de face debout montrant une scoliose thoracique à convexité gauche, avec mesure de l'angle de Cobb entre la vertèbre limite supérieure et la vertèbre limite inférieure\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">Radiographie du rachis en totalité, de face</span> (clichés réalisés en position <span class=\"kw-radio\">debout</span> quand l'enfant le peut). <span class=\"kw-etio\">Scoliose thoracique à convexité gauche</span> ; l'<span class=\"kw-radio\">angle de Cobb</span> se mesure entre la <span class=\"kw-radio\">vertèbre limite supérieure</span> et la <span class=\"kw-radio\">vertèbre limite inférieure</span> de la courbure. Source : banque imagerie « Imagerie à connaître » (item 47).</figcaption>\n      </figure>\n\n      <div class=\"callout callout-warn\">\n        <strong>Sur <span class=\"kw-clinique\">les</span> clichés</strong>\n        <ul>\n          <li>Compter <span class=\"kw-clinique\">les</span> vertèbres et identifier la malformation segmentaire ;</li>\n          <li>Mesurer l'<strong>angle de Cobb</strong> de la courbure ;</li>\n          <li>Rechercher des anomalies associées (cardiaques, rénales, urologiques) — séquences <strong>VACTERL</strong>.</li>\n        </ul>\n      </div>\n\n      <div class=\"callout callout-info\">\n        <strong>Examens complémentaires</strong> — <span class=\"kw-imagerie\">IRM</span> médullaire et <span class=\"kw-imagerie\">scanner</span> 3D souvent nécessaires pour planifier la <span class=\"kw-ttt\">chirurgie</span> · <span class=\"kw-imagerie\">échographie</span> rénale.\n      </div>","frequence":1},{"id":"47-31","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic de la cyphose thoracique de l’enfant","contenu":"<p>La cyphose = déformation dans le <strong>plan sagittal</strong>. Le diagnostic repose sur l'examen clinique du dos.</p>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Causes</h4>\n      <ul>\n        <li><strong>Augmentation de la cyphose physiologique thoracique</strong> — le plus souvent ;</li>\n        <li>Diminution voire inversion de la lordose cervicale ou lombaire — plus rare ;</li>\n        <li><strong>Dystrophie rachidienne de croissance</strong> = maladie de <strong><span class=\"kw-etio\">Scheuermann</span></strong> (1ʳᵉ cause de cyphose de l'<strong>adolescent</strong>) ;</li>\n        <li>Malformation <span class=\"kw-etio\">congénitale</span> ;</li>\n        <li>Maladie osseuse constitutionnelle.</li>\n      </ul>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Diagnostic clinique</h4>\n      <ul>\n        <li>Examen debout de profil → courbure thoracique exagérée vers l'avant ;</li>\n        <li>Antéflexion : cyphose persiste (différencie d'une attitude réductible) ;</li>\n        <li>Rechercher : raideur rachidienne, douleur, signes neurologiques.</li>\n      </ul>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Imagerie de confirmation</h4>\n      <ul>\n        <li><strong><span class=\"kw-imagerie\">Radiographie</span> du rachis</strong> debout face et profil ;</li>\n        <li>Mesure de l'<strong>angle de cyphose thoracique</strong> ;</li>\n        <li>Recherche de signes de <span class=\"kw-etio\">Scheuermann</span> : <strong><span class=\"kw-radio\">cunéiformisation vertébrale</span></strong>, <strong><span class=\"kw-radio\">nodules de Schmorl</span></strong>, irrégularités des plateaux.</li>\n      </ul>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Conséquences</h4>\n      <ul>\n        <li>Esthétiques essentiellement ;</li>\n        <li><strong>Douleurs</strong> à l'adolescence et à l'âge adulte.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong><span class=\"kw-alerte\">Drapeau rouge</span></strong> — Une <strong>raideur rachidienne</strong> peut révéler une infection (<span class=\"kw-etio\">spondylodiscite</span>) ou une tumeur osseuse/intracanalaire avant de conclure à des douleurs anorganiques.\n      </div>","frequence":0},{"id":"47-32","rang":"A","rubrique":"Définition","titre":"Connaître les examens médicaux obligatoires du nourrisson et de l’enfant","contenu":"<p><strong>20 examens obl<span class=\"kw-chiffre\">iga</span>toires</strong> de la naissance à<span class=\"kw-chiffre\"> 16 ans</span>, dont 14 dans <span class=\"kw-clinique\">les</span> 3 premières années.</p>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Calendrier complet</h4>\n      <ol>\n        <li><strong><span class=\"kw-chiffre\">8 jours</span> après la naissance</strong> (1) — <strong>certificat de santé</strong> ;</li>\n        <li>2ᵉ semaine (1) ;</li>\n        <li><span class=\"kw-chiffre\">1 à 6 mois</span> : <strong>1×/mois (6)</strong> ;</li>\n        <li><strong>9ᵉ mois</strong> (1) — <strong>certificat de santé</strong> ;</li>\n        <li>12ᵉ mois (1) ;</li>\n        <li>13ᵉ mois (1) ;</li>\n        <li><span class=\"kw-chiffre\">16–18 mois</span> (1) ;</li>\n        <li><strong>24 ou 25ᵉ mois</strong> (1) — <strong>certificat de santé</strong> ;</li>\n        <li><span class=\"kw-chiffre\">3–6 ans</span> : <strong>1×/an (4)</strong> ;</li>\n        <li><span class=\"kw-chiffre\">8–9 ans</span> (1) ;</li>\n        <li><span class=\"kw-chiffre\">11–13 ans</span> (1) ;</li>\n        <li><span class=\"kw-chiffre\">15–16 ans</span> (1).</li>\n      </ol>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">3 certificats de santé obl<span class=\"kw-chiffre\">iga</span>toires</h4>\n      <ul>\n        <li><strong>J8, M9, M24</strong> — feuillets mobiles insérés dans le carnet de santé ;</li>\n        <li><strong>Partie administrative</strong> remplie par <span class=\"kw-clinique\">les</span> <strong>parents</strong>, <strong>partie médicale</strong> par un <strong>médecin</strong> ;</li>\n        <li>Adressés au médecin responsable du service de <strong>PMI</strong> du département.</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Bucco-dentaire</strong> — 1ʳᵉ consultation dentaire <strong>vers <span class=\"kw-chiffre\">12 mois</span></strong> · Visites <strong>M'T dents</strong> tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">3 ans</span> à partir de <span class=\"kw-chiffre\">3 ans</span> (5 examens de <span class=\"kw-chiffre\">3 à 16 ans</span>, pris en charge à <strong><span class=\"kw-chiffre\">100 %</span></strong>).\n      </div>","frequence":1},{"id":"47-33","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la médecine scolaire","contenu":"<p>La <strong>médecine scolaire</strong> (service de promotion de la santé en faveur des élèves) dépend du <strong>ministère de l'Éducation nationale ✅</strong> (et non du ministère de la Santé ❌).</p>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Missions principales</h4>\n      <ul>\n        <li><strong>Intégration</strong> des enfants atteints de troubles de santé (pathologies chroniques, handicap) :\n          <ul>\n            <li>Mise en place de <strong>PAI</strong> (projets d'accueil individualisé) ;</li>\n            <li>Mise en place de <strong><span class=\"kw-def\">PPS</span></strong> (programmes personnalisés de soins).</li>\n          </ul>\n        </li>\n        <li><strong>Prévention</strong> :\n          <ul>\n            <li>Aide aux mesures de <strong><span class=\"kw-def\">dépistage</span> et prophylaxie</strong> en cas de maladie transmissible (<span class=\"kw-etio\">méningite</span>, TIAC, <span class=\"kw-etio\">tuberculose</span>…) ;</li>\n            <li>Missions d'<strong>information et d'éducation à la santé</strong> (addictions, sexualité, <span class=\"kw-etio\">obésité</span>) ;</li>\n            <li>Actions de protection de l'enfance en danger.</li>\n          </ul>\n        </li>\n        <li><strong>Examens</strong> :\n          <ul>\n            <li>Examen médical des <strong><span class=\"kw-chiffre\">6 ans</span></strong> (médecin) ;</li>\n            <li>Visite infirmière de <span class=\"kw-def\">dépistage</span> à <strong><span class=\"kw-chiffre\">12 ans</span></strong> (ATCD, entretien, poids/taille/IMC, dépistage visuel/auditif, bucco-dentaire, vaccinations).</li>\n          </ul>\n        </li>\n        <li><strong>Études épidémiologiques</strong> (indicateurs sanitaires et sociaux).</li>\n      </ul>","frequence":0},{"id":"47-34","rang":"A","rubrique":"Définition","titre":"Connaître les bilans de santé systématiques à l’âge scolaire et la coordination avec médecine scolaire","contenu":"<h4 style=\"margin:0 0 6px;font-size:14px;color:#1f2937;\">Bilan de la 4ᵉ année</h4>\n      <ul>\n        <li>Développement psychomoteur : enlève un vêtement, joue en groupe, <strong>tient sur un pied <span class=\"kw-chiffre\">3 sec</span></strong>, connaît son sexe, connaît <strong>3 couleurs</strong>, dessine bonhomme en 3 parties, phrases bien construites, propreté diurne et nocturne ;</li>\n        <li>Staturo-pondéral : IMC, <strong>âge du rebond d'adiposité</strong> (alerte si &lt;<span class=\"kw-chiffre\"> 6 ans</span>) ;</li>\n        <li>Dépistages sensoriels (AV, strabisme, audition à voix chuchotée) ;</li>\n        <li>Alimentation, vaccinations.</li>\n      </ul>\n      <p>Cherche à dépister : troubles sévères du langage oral, anomalies du comportement, signes d'inhibition/instabilité, situations à risque.</p>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Bilan de la 6ᵉ année (entrée au CP)</h4>\n      <ul>\n        <li>Évaluation neuropsychomotrice : troubles des apprentissages, affection neurologique méconnue, <strong>dyspraxies</strong>, <strong>dysgraphies</strong>, <strong>syncinésies</strong> ;</li>\n        <li>Motricité (latéralisation, orientation), comportement global ;</li>\n        <li><strong>TDAH</strong> décelable dès <span class=\"kw-chiffre\">3 ans</span>, mais le plus souvent reconnu à <strong><span class=\"kw-chiffre\">6 ans</span></strong> ;</li>\n        <li>Coordination PMI / médecine scolaire en fin de grande section.</li>\n      </ul>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Bilans <span class=\"kw-chiffre\">8-9 ans</span>,<span class=\"kw-chiffre\"> 11-13 ans</span>,<span class=\"kw-chiffre\"> 15-16 ans</span></h4>\n      <ul>\n        <li><strong>5 axes habituels</strong> + développement pubertaire (Tanner), examen vertébral (scoliose), peau (nævi, acné) ;</li>\n        <li><strong><span class=\"kw-chiffre\">9 ans</span></strong> : centré sur le <span class=\"kw-def\">dépistage</span> des <strong>troubles du langage écrit</strong> ;</li>\n        <li><strong><span class=\"kw-chiffre\">11–13 ans</span></strong> et <strong><span class=\"kw-chiffre\">15–16 ans</span></strong> : projets de vie, orientation, signes de mal-être, anomalies psychopathologiques ;</li>\n        <li>Consultation possible <strong>sans parent dès <span class=\"kw-chiffre\">11–12 ans</span></strong> ;</li>\n        <li><strong>HEADSS</strong> (Home, Education, Activities, Drugs, Sexuality, Suicidality) — repérage des comportements à risque.</li>\n      </ul>","frequence":0},{"id":"47-35","rang":"A","rubrique":"Définition","titre":"Connaître les éléments constitutifs du carnet de santé et leur utilité","contenu":"<p>Le <strong>carnet de santé</strong> est un outil de liaison <strong>indispensable</strong> à la connaissance médicale partagée de l'enfant.</p>\n\n      <div class=\"callout callout-warn\">\n        <strong>Secret professionnel</strong> — Strictement <strong>confidentiel</strong>, sa communication relève de la seule autorisation des parents. Toute personne y accédant est astreinte au secret professionnel.\n      </div>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Sections principales</h4>\n      <ul>\n        <li><strong>ATCD familiaux</strong>, données périnatales (période prénatale, accouchement, séjour maternité) ;</li>\n        <li><strong>Pathologies au long cours</strong>, allergies, maladies infectieuses ;</li>\n        <li><strong>Courbes de croissance</strong> staturo-pondérale ;</li>\n        <li>Synthèses des examens <strong>bucco-dentaires</strong> ;</li>\n        <li>Synthèses des examens de santé recommandés et contenu des consultations ;</li>\n        <li>Examens radiologiques, hospitalisations, transfusions, <strong>vaccinations</strong>.</li>\n      </ul>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Informations / conseils</h4>\n      <ul>\n        <li><strong>Repères du développement</strong> du nourrisson, enfant et adolescent ;</li>\n        <li>Conseils pratiques (<span class=\"kw-ci\">allaitement</span>, alimentation) ;</li>\n        <li>Conseils de <span class=\"kw-def\">surveillance</span> (colorimétrie selles, troubles sensoriels) ;</li>\n        <li>Conseils de prévention : MIN, bébé secoué, <span class=\"kw-etio\">obésité</span>, accidents domestiques, <strong>usage des écrans</strong> ;</li>\n        <li><strong>CAT face à situations pathologiques fréquentes</strong> : <span class=\"kw-clinique\">fièvre</span>, <span class=\"kw-clinique\">diarrhée</span>, <span class=\"kw-clinique\">vomissements</span>, gêne respiratoire.</li>\n      </ul>","frequence":0},{"id":"47-36","rang":"B","rubrique":"Prise en charge","titre":"Connaître les modalités d’organisation et d’indemnisation du suivi systématique obligatoire du nourrisson et de l’enfant","contenu":"<h4 style=\"margin:0 0 6px;font-size:14px;color:#1f2937;\">Organisation</h4>\n      <ul>\n        <li><strong>Médecin traitant</strong> (pédiatre ou généraliste) <strong>ou médecin de PMI</strong> : examens obl<span class=\"kw-chiffre\">iga</span>toires jusqu'à <strong><span class=\"kw-chiffre\">6 ans</span></strong> ;</li>\n        <li><strong>Médecin scolaire</strong> : peut réaliser <span class=\"kw-clinique\">les</span> examens à partir de la <strong>6ᵉ année</strong> ;</li>\n        <li>Coordination en fin de grande section de maternelle (avant l'entrée au CP) entre PMI et médecine scolaire.</li>\n      </ul>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Indemnisation</h4>\n      <ul>\n        <li>Consultations remboursées à <strong><span class=\"kw-chiffre\">100 %</span></strong> par l'Assurance Maladie ;</li>\n        <li>Visites <strong>M'T dents</strong> : 5 examens de <span class=\"kw-chiffre\">3 à 16 ans</span> pris en charge à<span class=\"kw-chiffre\"> 100 %</span>.</li>\n      </ul>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">PMI (Protection Maternelle et Infantile)</h4>\n      <ul>\n        <li>Service <strong>départemental</strong>, sous responsabilité du président du <strong>conseil départemental/général</strong> ;</li>\n        <li>Concerne <span class=\"kw-clinique\">les</span> enfants &lt; <strong><span class=\"kw-chiffre\">6 ans</span></strong> ;</li>\n        <li>Équipe pluridisciplinaire : médecins (pédiatres, généralistes, gynécologues), <strong>sages-femmes</strong>++, <strong>puéricultrices</strong>++, AS, psychologues, kiné ;</li>\n        <li>Consultations et visites à domicile <strong>gratuites</strong> ;</li>\n        <li>Rôles : prévention, <span class=\"kw-def\">dépistage</span> (dont maltraitance), handicap &lt;<span class=\"kw-chiffre\"> 6 ans</span>, contrôle des EAJE et assistantes maternelles, <span class=\"kw-def\">surveillance</span> épidémiologique (avis de naissance, certificats J8/M9/M24).</li>\n      </ul>","frequence":0},{"id":"47-37","rang":"B","rubrique":"Prise en charge","titre":"Connaître les modalités de rédaction des trois certificats médicaux accompagnant le suivi systématique obligatoire du nourrisson, aux 8e jour, 9e et 24e mois","contenu":"<p><strong>3 certificats de santé obl<span class=\"kw-chiffre\">iga</span>toires</strong> aux âges suivants : <strong>J8, M9, M24</strong>. Ce sont des <strong>feuillets mobiles</strong> insérés dans le carnet de santé.</p>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Structure des certificats</h4>\n      <ul>\n        <li><strong>Partie administrative</strong> : remplie par <span class=\"kw-clinique\">les</span> <strong>parents</strong> (informations sur le foyer, profession des parents…) ;</li>\n        <li><strong>Partie médicale</strong> : remplie par un <strong>médecin</strong> (état vaccinal, anomalies…).</li>\n      </ul>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Circuit de transmission</h4>\n      <ul>\n        <li>Documents <strong>adressés au médecin responsable du service de PMI du département</strong> ;</li>\n        <li>Permettent une <strong><span class=\"kw-def\">surveillance</span> épidémiologique</strong> à l'échelle départementale.</li>\n      </ul>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Qui peut rédiger ?</h4>\n      <ul>\n        <li>Médecin traitant (pédiatre, généraliste) <strong>en cabinet privé</strong> ;</li>\n        <li><strong>Médecin de PMI</strong>.</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <span class=\"kw-clinique\">Les</span> examens de J8, M9 et M24 sont mis en exergue dans le carnet de santé <strong>sur une double page</strong>, signifiant qu'ils se déroulent à des <strong>âges charnières</strong>, avec des données particulièrement importantes à recueillir.\n      </div>","frequence":0},{"id":"47-38","rang":"B","rubrique":"Prise en charge","titre":"Connaître les objectifs et les items contenus dans les trois certificats médicaux accompagnant le suivi systématique obligatoire du nourrisson","contenu":"<h4 style=\"margin:0 0 6px;font-size:14px;color:#1f2937;\">Examen du 8ᵉ jour (1ᵉʳ certificat)</h4>\n      <ul>\n        <li><strong>Quand ?</strong> Dans <span class=\"kw-clinique\">les</span> <strong><span class=\"kw-chiffre\">8 jours</span></strong>, habituellement avant la sortie de maternité ;</li>\n        <li><span class=\"kw-ci\">Grossesse</span> et accouchement : ATCD maternels/familiaux, gestité/parité, <span class=\"kw-def\">suivi</span> obstétrical, présentation, durée travail/RPM, voie d'accouchement, LA, <span class=\"kw-clinique\">fièvre</span> ;</li>\n        <li>État de l'enfant : <strong><span class=\"kw-def\">Apgar</span></strong>, paramètres (taille, poids, PC), gestes pratiqués ;</li>\n        <li>Examen physique : FR, FC, pouls, <strong>souffle</strong>, organomégalie, tonus, <strong><span class=\"kw-clinique\">ictère</span></strong> ;</li>\n        <li>Pathologies de la 1ʳᵉ semaine (<span class=\"kw-ttt\">oxygénothérapie</span>, intubation, ATB) ;</li>\n        <li>Dépistages : anomalies congénitales (fente labiopalatine, omphalocèle), sensoriels (visuel/auditif), orthopédique, <strong>test de Guthrie à <span class=\"kw-chiffre\">J3</span></strong> ;</li>\n        <li>Mode d'<span class=\"kw-ci\">allaitement</span>, supplémentations vitaminiques, prise de poids.</li>\n      </ul>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Examen du 9ᵉ mois (2ᵉ certificat)</h4>\n      <ul>\n        <li>ATCD : otites, affections respiratoires, accidents domestiques, hospitalisations ;</li>\n        <li>Affections actuelles : alimentation, sommeil, <span class=\"kw-clinique\">RGO</span>, <span class=\"kw-clinique\">eczéma</span>, anomalies organiques ;</li>\n        <li><strong>5 axes de <span class=\"kw-def\">suivi</span></strong> :\n          <ul>\n            <li>Psychomoteur : assis sans appui, déplace, motricité symétrique, pince pouce-index, pointe du doigt, prénom, syllabe, jeux ;</li>\n            <li>Staturo-pondéral : poids, taille, PC sur courbes ;</li>\n            <li>Sensoriels : strabisme, poursuite oculaire, audition (retournement) ;</li>\n            <li>Alimentation : <span class=\"kw-ci\">allaitement</span>, diversification ;</li>\n            <li><span class=\"kw-ttt\">Vaccination</span> : primovaccinations.</li>\n          </ul>\n        </li>\n      </ul>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Examen du 24ᵉ mois (3ᵉ certificat)</h4>\n      <ul>\n        <li>ATCD jusqu'à cet âge ;</li>\n        <li>5 axes : marche <span class=\"kw-etio\">acquise</span>, superpose objets, <strong>nomme une image</strong>, comprend consigne simple, associe 2 mots ;</li>\n        <li>IMC, dépistages sensoriels, alimentation, vaccinations (rappels) ;</li>\n        <li><strong><span class=\"kw-def\">Dépistage</span> précoce des signes d'autisme</strong>, <span class=\"kw-clinique\">évolution</span> dentition, conditions de vie.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>FR de saturnisme</strong> à évaluer à chaque examen de M9 à<span class=\"kw-chiffre\"> 6 ans</span> : habitat ancien, conduite d'eau en plomb, cas dans l'entourage, <strong>pica</strong>, activité parentale au plomb, arrivée récente d'un pays en développement. → <strong><span class=\"kw-chiffre\">≥ 1</span> FR = prescrire une plombémie</strong>.\n      </div>","frequence":0},{"id":"47-39","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les particularités de l’examen de suivi des adolescents","contenu":"<p>L'examen de l'adolescent ajoute aux 5 axes habituels des éléments spécifiques au développement pubertaire et au repérage de comportements à risque.</p>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Axes spécifiques</h4>\n      <ul>\n        <li><strong>Développement pubertaire</strong> : stades de <strong>Tanner</strong> ;</li>\n        <li>Examen de la <strong>statique vertébrale</strong> (<span class=\"kw-def\">dépistage</span> scoliose) ;</li>\n        <li>Examen de la <strong>peau</strong> : nævi, acné ;</li>\n        <li>Bilan <span class=\"kw-chiffre\">9 ans</span> : centré sur <strong>troubles du langage écrit</strong> ;</li>\n        <li>Bilans <span class=\"kw-chiffre\">11–13 ans</span> et <span class=\"kw-chiffre\">15–16 ans</span> : projets de vie, orientation, signes de mal-être, anomalies psychopathologiques.</li>\n      </ul>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Modalités d'examen</h4>\n      <ul>\n        <li>Consultation pouvant se faire <strong>en l'absence du parent dès <span class=\"kw-chiffre\">11–12 ans</span></strong> ;</li>\n        <li><strong>HEADSS</strong> (Home, Education, Activities, Drugs, Sexuality, Suicidality) — outil structuré pour aborder tous <span class=\"kw-clinique\">les</span> aspects de vie et comportements à risque (toxiques, sexualité, écrans) ;</li>\n        <li><strong>Sexualité</strong> abordée après début de puberté, selon la maturité.</li>\n      </ul>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Examen d'aptitude au sport chez l'enfant/adolescent</h4>\n      <ul>\n        <li>Pratique scolaire : enfant apte a priori ; dispenses ponctuelles certifiées par le médecin traitant ;</li>\n        <li>Pratique en club : certificat médical <strong>non obl<span class=\"kw-chiffre\">iga</span>toire</strong> depuis 2019, <strong>sauf disciplines à contraintes particulières</strong> (annuel) ; questionnaire de santé annuel par <span class=\"kw-clinique\">les</span> familles ;</li>\n        <li>Interrogatoire : croissance, puberté (Tanner), ATCD familiaux (cardiopathie, <span class=\"kw-alerte\">mort subite</span>, FR <span class=\"kw-bio\">CV</span>, hémostase), ATCD personnels ;</li>\n        <li>Clinique : auscultation, PA, neurosensoriel, locomoteur (scoliose, hyperlaxité) ;</li>\n        <li>Paraclinique : <strong><span class=\"kw-bio\">ECG</span> non systématique</strong> (HCSP) — Sté Fr Cardio : <span class=\"kw-bio\">ECG</span> dès <span class=\"kw-chiffre\">12 ans</span>.</li>\n      </ul>\n\n      <div class=\"callout callout-danger\">\n        🚩 <strong>Malaises ou syncopes à l'effort</strong> = signes d'alerte d'origine cardiaque → bilan complet : clinique + <strong><span class=\"kw-bio\">ECG</span> + test d'effort + <span class=\"kw-imagerie\">échocardiographie</span></strong>.\n      </div>","frequence":0},{"id":"47-40","rang":"A","rubrique":"Epidémiologie","titre":"Mortalité et morbidité infantiles","contenu":"<h4 style=\"margin:0 0 6px;font-size:14px;color:#1f2937;\">Définitions des mortalités</h4>\n      <table >\n        <thead><tr><th>Type</th><th>Période</th></tr></thead>\n        <tbody>\n          <tr><td>Mortinatalité</td><td>22 SA (ou &gt;<span class=\"kw-chiffre\"> 500 g</span>) → naissance</td></tr>\n          <tr><td><span class=\"kw-def\">Mortalité</span> périnatale</td><td>22 SA → <span class=\"kw-chiffre\">J7</span></td></tr>\n          <tr><td><strong><span class=\"kw-def\">Mortalité</span> néonatale précoce</strong></td><td>Naissance → <span class=\"kw-chiffre\">J7</span></td></tr>\n          <tr><td><span class=\"kw-def\">Mortalité</span> néonatale tardive</td><td><span class=\"kw-chiffre\">J7</span> → J28</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Mortalité</span> néonatale</strong></td><td>Naissance → <span class=\"kw-chiffre\">J28</span></td></tr>\n          <tr><td><span class=\"kw-def\">Mortalité</span> post-néonatale</td><td><span class=\"kw-chiffre\">J28</span> →<span class=\"kw-chiffre\"> 1 an</span></td></tr>\n          <tr><td><strong><span class=\"kw-def\">Mortalité</span> infantile</strong></td><td>Naissance →<span class=\"kw-chiffre\"> 1 an</span></td></tr>\n          <tr><td><span class=\"kw-def\">Mortalité</span> fœto-infantile</td><td>22 SA →<span class=\"kw-chiffre\"> 1 an</span></td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-def\">Mortalité</span> infantile en France</h4>\n      <ul>\n        <li><span class=\"kw-def\">Incidence</span> : <strong>4/1000</strong> · <span class=\"kw-clinique\">évolution</span> <strong>stable</strong> (<span class=\"kw-bio\">vs</span> diminution dans la plupart des pays européens) ;</li>\n        <li><strong>Moitié</strong> des décès dans la 1ʳᵉ semaine (néonatale précoce) ;</li>\n        <li>Surmortalité <strong>masculine de <span class=\"kw-chiffre\">30 %</span></strong> ;</li>\n        <li>Surmortalité dans <span class=\"kw-clinique\">les</span> <strong>DOM</strong> ;</li>\n        <li>Source : certificats de décès analysés par l'<strong>Inserm</strong>.</li>\n      </ul>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Causes de <span class=\"kw-def\">mortalité</span> selon l'âge</h4>\n      <table >\n        <thead><tr><th>Âge</th><th>Causes principales</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Néonatale</strong></td><td><strong>Endogènes</strong> : prématurité · malformations · mauvais déroulement de l'accouchement</td></tr>\n          <tr><td><strong>Post-néonatale</strong> (&gt;<span class=\"kw-chiffre\"> 1 mois</span>)</td><td><strong>Exogènes</strong> : <strong>MIN</strong> (France) · maladies infectieuses, malnutrition (pays en développement)</td></tr>\n          <tr><td><strong>&gt;<span class=\"kw-chiffre\"> 1 an</span></strong></td><td>1ʳᵉ cause : <strong>traumatologie</strong> · 2ᵉ : <strong>tumeur pédiatrique</strong></td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Causes de <span class=\"kw-def\">morbidité</span> infantile selon l'âge</h4>\n      <ul>\n        <li><strong>Nouveau-né</strong> : prématurité et conséquences ;</li>\n        <li><strong>&lt;<span class=\"kw-chiffre\"> 2 ans</span></strong> : infections respiratoires · <span class=\"kw-etio\">asthme</span> · <span class=\"kw-ci\">allergie</span> · <span class=\"kw-clinique\">eczéma</span> ;</li>\n        <li><strong>Âge scolaire</strong> : troubles des apprentissages · troubles mentaux/comportement · <span class=\"kw-etio\">obésité</span> ;</li>\n        <li><strong>Adolescent</strong> : tentatives de suicide · conduites addictives · troubles du comportement · pathologies somatopsychiques.</li>\n      </ul>","frequence":0},{"id":"47-41","rang":"A","rubrique":"Prise en charge","titre":"Accidents chez l’enfant : connaître les moyens de prévention","contenu":"<h4 style=\"margin:0 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-def\">Épidémiologie</span></h4>\n      <ul>\n        <li><strong><span class=\"kw-chiffre\">10–15 %</span></strong> des enfants victimes d'un accident chaque année ;</li>\n        <li>Âge le plus touché : <strong><span class=\"kw-chiffre\">1–4 ans</span></strong> ;</li>\n        <li>Sex-ratio : <strong>garçons (<span class=\"kw-chiffre\">60 %</span>)</strong> ;</li>\n        <li>Majorité <strong>bénins</strong> ; séquelles <span class=\"kw-chiffre\">2–5 %</span> (psychomotrices, esthétiques, fonctionnelles) ;</li>\n        <li><strong>~200 décès/an</strong> au décours d'un accident de la vie courante.</li>\n      </ul>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-def\">Facteurs de risque</span> selon l'âge</h4>\n      <table >\n        <thead><tr><th>Âge</th><th>Accidents typiques</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-chiffre\">0–1 an</span></strong></td><td>Asphyxies, accidents de literie</td></tr>\n          <tr><td><strong><span class=\"kw-chiffre\">1–4 ans</span></strong></td><td>Noyades, incendies, défenestrations, corps étrangers respiratoires</td></tr>\n          <tr><td><strong><span class=\"kw-chiffre\">4–10 ans</span></strong></td><td>Sports, loisirs, jeux dangereux, chocs directs, collisions</td></tr>\n          <tr><td><strong>&gt;<span class=\"kw-chiffre\"> 10 ans</span></strong></td><td>Expériences dangereuses (besoin d'indépendance, opposition)</td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">FR liés à l'entourage et au milieu</h4>\n      <ul>\n        <li><span class=\"kw-def\">Surveillance</span> insuffisante, vigilance trop faible ;</li>\n        <li>Famille monoparentale, fragilité socioculturelle/socio-économique ;</li>\n        <li>Environnement « conçu par <span class=\"kw-clinique\">les</span> adultes pour les adultes ».</li>\n      </ul>\n\n      <h4 style=\"margin:12px 0 6px;font-size:14px;color:#1f2937;\">Mesures de prévention</h4>\n      <ul>\n        <li><strong>Prévention passive</strong> : réglementation, législation (barrière de piscine, détecteur de fumée, normes jouets et mobiliers) ;</li>\n        <li><strong>Prévention active</strong> :\n          <ul>\n            <li>Promotion d'un <strong>environnement sécuritaire</strong> (maison, rue, école, loisirs) ;</li>\n            <li><strong>Éducation à la santé</strong> : apprentissage parental des capacités de l'enfant, <span class=\"kw-def\">surveillance</span> active des jeunes enfants.</li>\n          </ul>\n        </li>\n      </ul>\n\n      <div class=\"callout callout-danger\">\n        <strong>Jeux dangereux à dépister 🚨</strong>\n        <ul>\n          <li><strong>Jeux de non-oxygénation</strong> (jeu de la tomate dès <span class=\"kw-chiffre\">3–4 ans</span> · <strong>jeu du foulard</strong> entre <span class=\"kw-chiffre\">7–14 ans</span>) : risque d'<span class=\"kw-clinique\">œdème</span> cérébral, lésions cérébrales définitives (surdité, cécité), <strong>décès</strong> ;</li>\n          <li><strong>Jeux d'agression / harcèlement</strong> : traumatismes crâniens, fractures vertébrales, <strong>ruptures d'organes</strong> (foie, rate, rein), psychotraumatismes.</li>\n        </ul>\n      </div>","frequence":0}],"astuces":[{"type":"info","titre":"Construction en cours","contenu":"<p><span class=\"kw-clinique\">Les</span> astuces & pièges et la stratégie & CAT seront ajoutés au <strong>tour 3</strong> après finalisation des 41 objectifs.</p>"}],"strategie":{"urgence":"<p>Le <span class=\"kw-def\">suivi</span> pédiatrique vise à dépister chaque trouble pendant sa <strong>fenêtre de réversibilité</strong> : passé un certain âge, la PEC devient lourde ou <span class=\"kw-clinique\">les</span> séquelles deviennent définitives.</p><p><strong>Amblyopie <span class=\"q\">— <span class=\"kw-def\">dépistage</span> visuel</span></strong></p><p>Toute anomalie au <span class=\"kw-def\">dépistage</span> → <span class=\"kw-ttt\">avis ophtalmologique</span> sans attendre</p><ul><li>Toute anomalie visuelle non corrigée → amblyopie <span class=\"kw-alerte\">définitive après 6 ans</span> (maturation visuelle jusqu'à <span class=\"kw-chiffre\">10 ans</span>)</li><li><span class=\"kw-def\">Dépistage</span> : naissance · <span class=\"kw-chiffre\">M2</span> · <span class=\"kw-chiffre\">M4</span> · <span class=\"kw-chiffre\">M9–M24</span> · <span class=\"kw-chiffre\">3–4 ans</span> · <span class=\"kw-chiffre\">6 ans</span></li></ul><p><strong>Luxation <span class=\"kw-etio\">congénitale</span> de hanche <span class=\"q\">— LCH</span></strong></p><p><span class=\"kw-def\">Dépistage</span> clinique à chaque consultation <span class=\"kw-chiffre\">jusqu'à l'âge de la marche</span></p><ul><li>PEC ambulatoire dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">5 premières semaines</span> → guérison complète sans séquelles</li><li>Diagnostic <span class=\"kw-chiffre\">après 3 mois</span> → en moyenne <span class=\"kw-chiffre\">20 jours d'hospitalisation</span>, risque de séquelles</li></ul><p><strong>Surdité de l'enfant</strong></p><ul><li>Risque majeur = <span class=\"kw-alerte\">trouble de la communication orale</span>, surtout si surdité avant <span class=\"kw-chiffre\">18 mois–2 ans</span></li><li><span class=\"kw-ttt\">Appareillage</span> le plus précoce possible si surdité moyenne à profonde + <span class=\"kw-ttt\">orthophonie</span> systématique</li></ul>","hospit":"<p>Le médecin traitant (ou de PMI) <strong>dépiste</strong> ; il <strong>adresse au spécialiste</strong> tout signe d'appel, <span class=\"kw-def\">facteur de risque</span> ou anomalie au <span class=\"kw-def\">dépistage</span>.</p><p><strong>Ophtalmologiste</strong></p><p>Urgences sans délai : <span class=\"kw-alerte\">leucocorie</span>, <span class=\"kw-alerte\">strabisme constant</span>, nystagmus, cornée trouble</p><ul><li>Tout signe d'appel ou anomalie au <span class=\"kw-def\">dépistage</span> (<span class=\"kw-clinique\">strabisme</span>, retard de préhension, <span class=\"kw-clinique\">céphalées</span>…)</li><li>FR visuels → examen avec réfraction sous cycloplégie entre <span class=\"kw-chiffre\">M3–M12</span></li></ul><p><strong>ORL</strong></p><p>Confirmation par épreuves objectives (<span class=\"kw-bio\">PEA</span> + <span class=\"kw-bio\">ASSR</span>)</p><ul><li>Tout signe d'appel auditif, FR ou anomalie au <span class=\"kw-def\">dépistage</span></li><li>Tout <span class=\"kw-clinique\">retard de parole et de langage</span> après <span class=\"kw-chiffre\">3 ans</span></li></ul><p><strong>Chirurgien-dentiste / orthodontiste</strong></p><ul><li>1ʳᵉ consultation dentaire entre <span class=\"kw-chiffre\">12 et 18 mois</span>, puis « M'T dents » tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">3 ans</span> dès <span class=\"kw-chiffre\">3 ans</span></li><li>Trouble de l'articulé dentaire → <span class=\"kw-ttt\">orthodontiste</span> <span class=\"kw-chiffre\">avant 16 ans</span></li></ul><p><strong>Orthopédiste pédiatre</strong></p><ul><li><span class=\"kw-def\">LCH</span> : anomalie clinique ou FR → <span class=\"kw-imagerie\">échographie</span> (&lt;<span class=\"kw-chiffre\"> 4 mois</span>) ou <span class=\"kw-imagerie\">radiographie</span> (<span class=\"kw-chiffre\">≥ 4 mois</span>) + avis</li><li><span class=\"kw-def\">Scoliose</span> évolutive · déformation d'axe pathologique (hors âge, asymétrique, douloureuse) → <span class=\"kw-imagerie\">radiographies</span> + avis</li></ul>","redflags":"<ul><li><span class=\"kw-alerte\">Leucocorie</span> → <span class=\"kw-etio\">rétinoblastome</span>, <span class=\"kw-etio\">cataracte congénitale</span> (<span class=\"kw-alerte\">urgence</span> ophtalmologique)</li><li><span class=\"kw-alerte\">Strabisme constant</span> · <span class=\"kw-alerte\">nystagmus</span> · cornée trouble · mégalocornée</li><li><span class=\"kw-alerte\">Malaise ou syncope à l'effort</span> → origine <span class=\"kw-etio\">cardiaque</span> (bilan : <span class=\"kw-bio\">ECG</span> + test d'effort + <span class=\"kw-imagerie\">échocardiographie</span>)</li><li><span class=\"kw-alerte\">Raideur rachidienne</span> → éliminer <span class=\"kw-etio\">spondylodiscite</span> ou <span class=\"kw-etio\">tumeur</span> avant de conclure à des douleurs anorganiques</li><li>Scoliose avec <span class=\"kw-clinique\">angiome / touffe pileuse</span>, <span class=\"kw-clinique\">taches café-au-lait</span> ou anomalies neurologiques → scoliose <span class=\"kw-etio\">non idiopathique</span></li><li><span class=\"kw-alerte\">Saturnisme</span> : <span class=\"kw-clinique\">pica</span> + habitat ancien (<span class=\"kw-chiffre\">≥ 1</span> FR) → prescrire une <span class=\"kw-bio\">plombémie</span></li><li>Jeux dangereux : <span class=\"kw-alerte\">jeu du foulard</span> (<span class=\"kw-chiffre\">7–14 ans</span>), jeux d'agression → lésions cérébrales, ruptures d'organes</li></ul>","principes":"<p>La <strong>prévention</strong> incombe à <strong>tout médecin</strong> (la PEC curative spécialisée relève du dentiste, de l'ORL, de l'ophtalmologiste ou de l'orthopédiste).</p><p><strong>Prévention de la carie dentaire</strong></p><p><span class=\"kw-ttt\">Fluorures systémiques</span> seulement si risque carieux élevé · <span class=\"kw-ci\">non recommandés avant 6 mois</span> (risque de fluorose)</p><ul><li><span class=\"kw-ttt\">Brossage 2×/jour</span> dès l'apparition des dents (<span class=\"kw-chiffre\">6 mois</span>), <span class=\"kw-ttt\">dentifrice fluoré</span> adapté à l'âge (par <span class=\"kw-clinique\">les</span> parents jusqu'à<span class=\"kw-chiffre\"> 6 ans</span>)</li><li>Hygiène alimentaire : limiter <span class=\"kw-clinique\">les</span> sucres hors repas, pas de biberon sucré à l'endormissement</li><li><span class=\"kw-ttt\">Scellement des sillons</span> des 1ʳᵉˢ et 2ᵉˢ molaires définitives</li></ul><p><strong>Prévention des accidents</strong></p><ul><li><span class=\"kw-chiffre\">10–15 %</span> des enfants/an ; pic entre <span class=\"kw-chiffre\">1–4 ans</span> ; ~<span class=\"kw-chiffre\">200 décès/an</span> (accidents de la vie courante)</li><li>Prévention <strong>passive</strong> : réglementation (barrière de piscine, détecteur de fumée, normes jouets)</li><li>Prévention <strong>active</strong> : environnement sécuritaire + éducation à la santé (<span class=\"kw-def\">surveillance</span> active des jeunes enfants)</li></ul>","suivi":"<p><strong>Calendrier des examens obl<span class=\"kw-chiffre\">iga</span>toires</strong></p><ul><li><span class=\"kw-chiffre\">20 examens</span> obl<span class=\"kw-chiffre\">iga</span>toires jusqu'à<span class=\"kw-chiffre\"> 16 ans</span>, dont <span class=\"kw-chiffre\">14</span> dans <span class=\"kw-clinique\">les</span> 3 premières années (<span class=\"kw-chiffre\">6</span> entre <span class=\"kw-chiffre\">4–17 ans</span>)</li><li>Consultations <strong>remboursées à<span class=\"kw-chiffre\"> 100 %</span></strong> · orientées sur <span class=\"kw-clinique\">les</span> 5 axes de <span class=\"kw-def\">surveillance</span> évolutive</li></ul><p><strong>Qui réalise le <span class=\"kw-def\">suivi</span> ?</strong></p><ul><li>Médecin traitant (pédiatre / généraliste) ou <span class=\"kw-def\">médecin de PMI</span> : jusqu'à <span class=\"kw-chiffre\">6 ans</span></li><li><span class=\"kw-def\">Médecin scolaire</span> : à partir de la 6ᵉ année (examen des <span class=\"kw-chiffre\">6 ans</span>, visite infirmière à<span class=\"kw-chiffre\"> 12 ans</span>)</li></ul><p><strong>3 certificats de santé obl<span class=\"kw-chiffre\">iga</span>toires</strong></p><ul><li>Aux âges charnières <span class=\"kw-chiffre\">J8</span> · <span class=\"kw-chiffre\">M9</span> · <span class=\"kw-chiffre\">M24</span> (feuillets mobiles du carnet de santé)</li><li>Partie administrative par <span class=\"kw-clinique\">les</span> parents, partie médicale par un médecin → adressés à la <span class=\"kw-def\">PMI</span> du département</li></ul><p><strong>Carnet de santé</strong></p><ul><li>Outil de liaison <strong>strictement confidentiel</strong> (secret professionnel)</li><li>Courbes de croissance, vaccinations, dépistages, conseils de prévention et CAT (<span class=\"kw-clinique\">fièvre</span>, <span class=\"kw-clinique\">diarrhée</span>, <span class=\"kw-clinique\">vomissements</span>)</li></ul>"},"liensGlobaux":[{"href":"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/croissance-developpement/suivi-medical-pediatrique","label":"Collège Pédiatrie — Suivi médical pédiatrique"}],"cards":[{"i":"5fab8e439b81","n":47,"o":"47-1","u":"Définition","t":"Connaître les définitions des tranches d’âge des enfants","q":"Comment sont définis le jeune et le grand enfant en pédiatrie ?","a":"<p>La tranche d'âge du <strong>jeune et grand enfant</strong> s'étend de <strong>2 ans</strong> jusqu'au <strong>début de la puberté</strong>.</p>"},{"i":"9d8390b58077","n":47,"o":"47-1","u":"Définition","t":"Connaître les définitions des tranches d’âge des enfants","q":"Quelle est la définition de la tranche d'âge du nourrisson ?","a":"<p>La tranche d'âge du <strong>nourrisson</strong> débute à <strong>1 mois</strong> et s'étend jusqu'à <strong>2 ans</strong>.</p>"},{"i":"bb5471b30bc6","n":47,"o":"47-1","u":"Définition","t":"Connaître les définitions des tranches d’âge des enfants","q":"Comment est définie la tranche d'âge du nouveau-né en pédiatrie ?","a":"<p>En pédiatrie, le <strong>nouveau-né</strong> correspond à la période <strong>inférieure à 1 mois</strong> après la naissance.</p>"},{"i":"df563f733ec1","n":47,"o":"47-1","u":"Définition","t":"Connaître les définitions des tranches d’âge des enfants","q":"Quand débute la tranche d'âge de l'adolescent ?","a":"<p>L'adolescence est définie comme la période débutant <strong>après le début de la puberté</strong>.</p>"},{"i":"32306d8477eb","n":47,"o":"47-10","u":"Définition","t":"Connaître les modalités du dépistage systématique des troubles auditifs","q":"Quels sont les examens de dépistage auditif obligatoires pratiqués en maternité chez tous les nouveau-nés ?","a":"<p>Les examens de dépistage auditif obligatoires en maternité sont les <strong>OEAP</strong> (otoémissions acoustiques provoquées) et/ou les <strong>PEAA</strong> (potentiels évoqués auditifs automatisés).</p>"},{"i":"473f51e22c11","n":47,"o":"47-10","u":"Définition","t":"Connaître les modalités du dépistage systématique des troubles auditifs","q":"Quels sont les examens de dépistage auditif recommandés à 9 mois dans le cadre du suivi médical ?","a":"<p>À 9 mois, le dépistage inclut la recherche de réactions aux <strong>bruits familiers</strong>, la réaction au <strong>prénom</strong> et l'utilisation de <strong>boîtes à retournement</strong>.</p>"},{"i":"7a6703bbe789","n":47,"o":"47-10","u":"Définition","t":"Connaître les modalités du dépistage systématique des troubles auditifs","q":"Pourquoi le dépistage auditif doit-il être répété au-delà de la période néonatale ?","a":"<p>Le dépistage doit être répété en raison de l'existence :<ul><li>D'atteintes génétiques se manifestant par une <strong>surdité évolutive</strong>.</li><li>De surdités <strong>acquises</strong> après la période néonatale, comme celles suite à une méningite.</li></ul></p>"},{"i":"a3ffaac59335","n":47,"o":"47-10","u":"Définition","t":"Connaître les modalités du dépistage systématique des troubles auditifs","q":"Quand le système auditif est-il fonctionnel chez le fœtus ?","a":"<p>Le système auditif est fonctionnel <strong>dès avant la naissance</strong>, car l'oreille interne est mature précocement.</p>"},{"i":"e27147edb26b","n":47,"o":"47-10","u":"Définition","t":"Connaître les modalités du dépistage systématique des troubles auditifs","q":"Quelle est l'incidence des anomalies auditives chez l'enfant de moins de 6 ans ?","a":"<p>Environ <strong>5 %</strong> des enfants de moins de 6 ans présentent une anomalie auditive.</p>"},{"i":"e8002c31269b","n":47,"o":"47-10","u":"Définition","t":"Connaître les modalités du dépistage systématique des troubles auditifs","q":"Quel est l'examen de dépistage auditif réalisé à l'âge de 6 ans ?","a":"<p>À 6 ans, l'examen de dépistage est un <strong>audiogramme du médecin scolaire</strong>, incluant un test de désignation et une audiométrie tonale.</p>"},{"i":"22994dd7516d","n":47,"o":"47-2","u":"Prise en charge","t":"Connaître les éléments d’interrogatoire et d’examen clinique systématique d’un enfant en fonction de son âge et du contexte","q":"Quels sont les principaux dépistages sensoriels et orthopédiques réalisés lors de l'examen clinique systématique en pédiatrie ?","a":"<p>Les principaux dépistages réalisés lors de l'examen clinique systématique en pédiatrie sont :</p><ul><li>Les <strong>dépistages sensoriels</strong> : visuels et auditifs.</li><li>Les <strong>dépistages orthopédiques</strong> :</li><ul><li>La <strong>luxation congénitale de la hanche (LCH)</strong> jusqu'à l'acquisition de la marche.</li><li>La recherche d'une <strong>scoliose</strong> à l'adolescence.</li></ul></ul>"},{"i":"32e49b11e27c","n":47,"o":"47-2","u":"Prise en charge","t":"Connaître les éléments d’interrogatoire et d’examen clinique systématique d’un enfant en fonction de son âge et du contexte","q":"Quels sont les éléments clés à interroger concernant les antécédents familiaux lors d'un suivi médical pédiatrique ?","a":"<p>Lors d'un suivi médical pédiatrique, les éléments clés à interroger concernant les antécédents familiaux sont :</p><ul><li>Les <strong>pathologies familiales</strong>.</li><li>Les cas de <strong>mort subite</strong>.</li><li>Les <strong>facteurs de risque cardiovasculaires (FR CV)</strong>.</li><li>Les <strong>maladies héréditaires</strong>.</li></ul>"},{"i":"5503d3a27314","n":47,"o":"47-2","u":"Prise en charge","t":"Connaître les éléments d’interrogatoire et d’examen clinique systématique d’un enfant en fonction de son âge et du contexte","q":"Quels aspects de l'environnement de l'enfant sont importants à recueillir lors d'un interrogatoire en pédiatrie ?","a":"<p>Lors d'un interrogatoire en pédiatrie, les aspects importants de l'environnement de l'enfant à recueillir sont :</p><ul><li>Le <strong>mode de garde</strong>.</li><li>La présence de <strong>fratrie</strong>.</li><li>La présence d'<strong>animaux</strong> domestiques.</li><li>Les caractéristiques de l'<strong>habitat</strong> (notamment pour dépister un risque de <strong>saturnisme</strong>).</li><li>L'<strong>exposition aux écrans</strong>.</li></ul>"},{"i":"698ec6c87bc3","n":47,"o":"47-2","u":"Prise en charge","t":"Connaître les éléments d’interrogatoire et d’examen clinique systématique d’un enfant en fonction de son âge et du contexte","q":"Quels sont les paramètres de croissance systématiquement mesurés et suivis chez l'enfant ?","a":"<p>Les paramètres de croissance systématiquement mesurés et suivis chez l'enfant sont :</p><ul><li>Le <strong>poids</strong>.</li><li>La <strong>taille</strong>.</li><li>Le <strong>périmètre crânien (PC)</strong> jusqu'à l'âge de <strong>3 ans</strong>.</li><li>L'<strong>IMC</strong> (Indice de Masse Corporelle).</li></ul><p>Ces données sont systématiquement reportées sur les <strong>courbes de croissance</strong>.</p>"},{"i":"84e1053a5a61","n":47,"o":"47-2","u":"Prise en charge","t":"Connaître les éléments d’interrogatoire et d’examen clinique systématique d’un enfant en fonction de son âge et du contexte","q":"Quels antécédents personnels sont systématiquement recherchés lors d'un interrogatoire en pédiatrie ?","a":"<p>Les antécédents personnels systématiquement recherchés lors d'un interrogatoire en pédiatrie sont :</p><ul><li>Les informations sur la <strong>grossesse</strong> et l'<strong>accouchement</strong>.</li><li>Les événements de la <strong>période néonatale</strong>.</li><li>Les <strong>hospitalisations</strong> antérieures.</li><li>Les <strong>allergies</strong> et <strong>intolérances</strong> connues.</li><li>Le statut <strong>vaccinal</strong> (calendrier obligatoire et recommandé).</li></ul>"},{"i":"c94689f09ae0","n":47,"o":"47-2","u":"Prise en charge","t":"Connaître les éléments d’interrogatoire et d’examen clinique systématique d’un enfant en fonction de son âge et du contexte","q":"À quel âge le statut pubertaire de l'enfant est-il évalué et selon quelle échelle ?","a":"<p>Le statut pubertaire de l'enfant est évalué après l'âge de <strong>8 ans</strong>, selon l'<strong>échelle de Tanner</strong>.</p>"},{"i":"52017c4d976b","n":47,"o":"47-4","u":"Définition","t":"Connaître le dépistage systématique des troubles visuels","q":"Quand un examen ophtalmologique avec réfraction et cycloplégie est-il recommandé en cas de facteurs de risque spécifiques pour les troubles visuels chez l'enfant ?","a":"<p>Un examen ophtalmologique avec réfraction après cycloplégie est recommandé <strong>entre M3 et M12</strong> en présence de <strong>facteurs de risque</strong>.</p>"},{"i":"6f3cc9ba598b","n":47,"o":"47-4","u":"Définition","t":"Connaître le dépistage systématique des troubles visuels","q":"À quels âges clés est recommandé le dépistage systématique des troubles visuels chez l'enfant en âge préscolaire ?","a":"<ul><li><strong>Naissance</strong> (en maternité)</li><li><strong>M2</strong></li><li><strong>M4</strong></li><li><strong>Entre M9 et M24</strong></li></ul>"},{"i":"a884c11d7930","n":47,"o":"47-4","u":"Définition","t":"Connaître le dépistage systématique des troubles visuels","q":"Jusqu'à quel âge le système visuel de l'enfant est-il considéré comme immature et quel est l'impact d'une perturbation durant cette période ?","a":"<p>Le système visuel est immature à la naissance et son développement se poursuit <strong>jusqu'à 10 ans</strong>. Toute perturbation peut entraîner une <strong>amblyopie</strong>, classiquement définitive après <strong>6 ans</strong>.</p>"},{"i":"d1b78b24a348","n":47,"o":"47-4","u":"Définition","t":"Connaître le dépistage systématique des troubles visuels","q":"Quelle est la prévalence des anomalies visuelles chez les enfants de moins de 6 ans et quel est l'intérêt du dépistage systématique ?","a":"<p>Près de <strong>15 à 20 %</strong> des enfants de moins de 6 ans présentent une anomalie visuelle. Le dépistage systématique permet une <strong>prise en charge précoce</strong> et assure un <strong>pronostic visuel optimal</strong>.</p>"},{"i":"f2459482970c","n":47,"o":"47-4","u":"Définition","t":"Connaître le dépistage systématique des troubles visuels","q":"À quels âges précis est recommandé le dépistage systématique des troubles visuels chez l'enfant en âge scolaire ?","a":"<ul><li><strong>3-4 ans</strong></li><li><strong>6 ans</strong></li></ul>"},{"i":"4cd12536d501","n":47,"o":"47-7","u":"Prise en charge","t":"Connaître les indications d’adressage d’un enfant à un ophtalmologiste","q":"Quels sont les signes d'appel visuels chez un enfant de 2 à 5 ans qui nécessitent un avis ophtalmologique ?","a":"<ul><li><strong>Dyspraxies</strong></li><li><strong>Retard de langage</strong></li><li><strong>Lenteur d'exécution</strong></li><li><strong>Fatigabilité</strong></li></ul>"},{"i":"51411b56861e","n":47,"o":"47-7","u":"Prise en charge","t":"Connaître les indications d’adressage d’un enfant à un ophtalmologiste","q":"Quelles sont les urgences ophtalmologiques pédiatriques imposant un adressage sans délai ?","a":"<ul><li><strong>Leucocorie</strong> (pouvant faire suspecter un <strong>rétinoblastome</strong> ou une <strong>cataracte congénitale</strong>)</li><li><strong>Cornée trouble</strong></li><li><strong>Mégalocornée</strong></li><li><strong>Strabisme constant</strong></li><li><strong>Nystagmus</strong></li></ul>"},{"i":"e735820a28e1","n":47,"o":"47-7","u":"Prise en charge","t":"Connaître les indications d’adressage d’un enfant à un ophtalmologiste","q":"Quelles sont les indications générales d'adressage d'un enfant à un ophtalmologiste, quel que soit l'âge ?","a":"<p>Tout <strong>signe d'appel</strong> ou <strong>anomalie au dépistage</strong> impose un avis ophtalmologique spécialisé.</p>"},{"i":"e76b0b86befa","n":47,"o":"47-7","u":"Prise en charge","t":"Connaître les indications d’adressage d’un enfant à un ophtalmologiste","q":"Chez un enfant plus âgé, quels sont les signes d'appel visuels pouvant justifier une consultation ophtalmologique ?","a":"<ul><li><strong>Lecture trop rapprochée</strong></li><li><strong>Confusion de lettres</strong></li><li><strong>Céphalées</strong></li><li><strong>Plissements palpébraux</strong></li><li><strong>Rougeur, prurit oculaire</strong></li></ul>"},{"i":"f3aa78bd1c80","n":47,"o":"47-7","u":"Prise en charge","t":"Connaître les indications d’adressage d’un enfant à un ophtalmologiste","q":"Quels sont les signes d'appel visuels chez un enfant de moins de 4 mois qui nécessitent un avis ophtalmologique ?","a":"<ul><li><strong>Leucocorie</strong></li><li><strong>Strabisme</strong></li><li><strong>Nystagmus</strong></li><li><strong>Torticolis</strong></li><li><strong>Signe digito-oculaire</strong></li><li><strong>Manque d'intérêt visuel</strong> (absence du réflexe de fixation à M1, absence de clignement à la menace à M3, absence de poursuite oculaire à M4)</li><li><strong>Retard d'acquisition de la préhension</strong> (normalement vers M5)</li></ul>"},{"i":"fa6de01b51a1","n":47,"o":"47-7","u":"Prise en charge","t":"Connaître les indications d’adressage d’un enfant à un ophtalmologiste","q":"Quels sont les signes d'appel visuels chez un enfant entre 6 mois et l'âge verbal qui nécessitent un avis ophtalmologique ?","a":"<ul><li><strong>Indifférence à l'entourage</strong></li><li>Enfant qui <strong>se cogne, tombe</strong></li><li><strong>Plisse les yeux</strong></li><li><strong>Ferme un œil au soleil</strong> (signe de l'éventail)</li></ul>"},{"i":"14dc8eed2499","n":47,"o":"47-9","u":"Diagnostic positif","t":"Connaître les signes fonctionnels et physiques évocateurs de malvoyance chez l’enfant","q":"Quel bilan paraclinique est indiqué devant des signes évocateurs de malvoyance chez l'enfant ?","a":"<p>Le bilan paraclinique indiqué devant des signes évocateurs de malvoyance chez l'enfant comprend :</p><ul><li>Un <strong>bilan ophtalmologique complet</strong> (recherche d'anomalie pupillaire, de leucocorie, etc.).</li><li>Un <strong>fond d'œil</strong>.</li><li>Des <strong>Potentiels Évoqués Visuels (PEV)</strong>.</li><li>Un <strong>électrorétinogramme (ERG)</strong>.</li><li>Une <strong>imagerie des voies optiques et cérébrale</strong>.</li></ul>"},{"i":"4ac9f9541f8a","n":47,"o":"47-9","u":"Diagnostic positif","t":"Connaître les signes fonctionnels et physiques évocateurs de malvoyance chez l’enfant","q":"Quels sont les signes fonctionnels et physiques évocateurs de malvoyance chez le jeune enfant, et particulièrement ceux liés au comportement oculaire ?","a":"<p>Les signes évocateurs de malvoyance chez le jeune enfant incluent :</p><ul><li>Un <strong>nystagmus</strong>.</li><li>Un <strong>strabisme</strong>.</li><li>Une <strong>errance du regard</strong>.</li><li>Le <strong>signe digito-oculaire</strong> (pression digitale régulière des globes oculaires).</li><li>Une <strong>indifférence visuelle</strong> lors de l'évaluation de la fixation, de la poursuite oculaire ou de la préhension d'objets.</li></ul>"},{"i":"605ee32bf55e","n":47,"o":"47-9","u":"Diagnostic positif","t":"Connaître les signes fonctionnels et physiques évocateurs de malvoyance chez l’enfant","q":"Quelles sont les principales causes de malvoyance à rechercher chez l'enfant de moins de 1 an ?","a":"<p>Les principales causes de malvoyance à rechercher chez l'enfant de moins de 1 an sont :</p><ul><li>Un simple <strong>retard de maturation fovéolaire</strong>, qui se résout souvent spontanément.</li><li>Des <strong>cécités congénitales organiques</strong>, telles que :<ul><li>Une <strong>dégénérescence rétinienne</strong>.</li><li>Une <strong>atrophie optique</strong>.</li><li>Une <strong>cécité corticale</strong>.</li></ul></li></ul>"}]};